/* MIT. Managed document processing in the original research workspace. */
.pipelines-panel { color: #222; }
.pipelines-panel h3 { margin: 0 0 .7rem; }
.pipelines-panel h4 { margin: 1.2rem 0 .55rem; font-size: .95rem; }
.pipelines-panel label { display: flex; flex-direction: column; gap: .35rem; min-width: 0; font-size: .87rem; }
.pipelines-panel input, .pipelines-panel select, .pipelines-panel textarea { min-width: 0; width: 100%; box-sizing: border-box; background: #fff; color: #222; border: 1px solid #aaa; border-radius: 3px; padding: .55rem; }
.pipelines-panel input[type=file] { padding: .55rem; }
.pipelines-panel textarea { resize: vertical; }
.pipelines-panel button { background: #fff; color: #222; border: 1px solid #999; border-radius: 3px; padding: .55rem .75rem; font: inherit; font-size: .85rem; cursor: pointer; }
