import { canonicalBytes, digest, need, object } from '../node/unstructured/contract.mjs';
import {
  createPartitionEditionProvider, verifyPartitionResearchEnvelope, receivePartitionEnvelope,
} from '../node/unstructured/dossier.mjs';
import { decodePartitionBytes } from '../node/unstructured/purchase.mjs';
import { PARTITION_LIMITS } from '../node/unstructured/contract.mjs';

const nativeRuntime = resolve(fileURLToPath(new URL('../', import.meta.url)));
const HEX = /^[a-f0-9]{64}$/;
const ID = /^u_[a-f0-9]{64}$/;
const copy = value => structuredClone(value);
const sourceRoute = operation => {
  if (operation?.method !== 'POST' || typeof operation.url !== 'string') return null;
  try {
    const url = new URL(operation.url);
    return /^\/documents\/unstructured\/([a-z][a-z0-9-]{0,39})$/.exec(url.pathname)?.[1] ?? null;
  } catch { return null; }
};
const safeFilename = (name, fallback) => {
  const value = typeof name === 'string' ? name.replace(/[^A-Za-z0-9._-]/g, '_').slice(0,150) : '';
  return /^[A-Za-z0-9]/.test(value) ? value : fallback;
};
const metadata = purchase => ({
  filename: purchase.document.filename, contentType: purchase.document.contentType,
  bytes: purchase.document.bytes, sha256: purchase.document.sha256,
});
function selected(value) {
  need(object(value) && Object.keys(value).every(key => ['purchaseId','editionId'].includes(key)) &&
    [typeof value.purchaseId === 'string', typeof value.editionId === 'string'].filter(Boolean).length === 1,
  'UNSTRUCTURED_ONE_DOCUMENT_SELECTION_REQUIRED');
  if (value.purchaseId !== undefined) need(ID.test(value.purchaseId), 'UNSTRUCTURED_PURCHASE_ID_INVALID');
  if (value.editionId !== undefined) need(/^e_[a-f0-9]{64}$/.test(value.editionId), 'UNSTRUCTURED_EDITION_ID_INVALID');
  return copy(value);
}
function requestedHash(value) {
  need(typeof value === 'string' && HEX.test(value), 'UNSTRUCTURED_REVIEWED_EDITION_REQUIRED');
  return value;
}

/** Open a launcher-selected original buyer source; browser requests never provide these paths. */
export async function openSavedDocumentBuyerSource(configPath) {
  need(typeof configPath === 'string' && isAbsolute(configPath) && resolve(configPath) === configPath,
    'UNSTRUCTURED_DOCUMENT_SOURCE_PATH_REQUIRED');
  const value = await readJson(configPath, 1024 * 1024);
  need(object(value) && value.schema === 'stellar-forge.unstructured-document-source.v1' &&
    Object.keys(value).every(key => ['schema','workspaceId','runtimeDirectory','stateDirectory','inboxDirectory'].includes(key)),
  'UNSTRUCTURED_DOCUMENT_SOURCE_CONFIG_INVALID');
  need(typeof value.workspaceId === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(value.workspaceId),
    'UNSTRUCTURED_WORKSPACE_ID_REQUIRED');
  const runtimeDirectory = value.runtimeDirectory ?? nativeRuntime;
  const stateDirectory = value.stateDirectory ?? value.inboxDirectory;
  for (const path of [runtimeDirectory,stateDirectory,...(value.inboxDirectory === undefined ? [] : [value.inboxDirectory])]) {
    need(typeof path === 'string' && isAbsolute(path) && resolve(path) === path,
      'UNSTRUCTURED_DOCUMENT_SOURCE_ABSOLUTE_PATHS_REQUIRED');
    need((await stat(path)).isDirectory(), 'UNSTRUCTURED_DOCUMENT_SOURCE_DIRECTORY_REQUIRED');
  }
  const buyer = new Buyer({runtimeDirectory,stateDirectory});
  return {buyer,runtimeDirectory,workspaceId:value.workspaceId,
    ...(value.inboxDirectory === undefined ? {} : {inboxDirectory:value.inboxDirectory})};
}

/** Host supplies the original buyer/inbox once. Browser selections contain no filesystem path. */
export async function openUnstructuredWorkspace({
  dossiers, buyer = null, workspaceId, inboxDirectory,
  runtimeDirectory = buyer?.runtime.directory ?? nativeRuntime,
} = {}) {
  need(dossiers && typeof dossiers.get === 'function' && typeof dossiers.readRetainedEdition === 'function',
    'UNSTRUCTURED_ORIGINAL_RETAINED_EDITION_READER_REQUIRED');
  need(buyer === null || buyer instanceof Buyer, 'ORIGINAL_DOCUMENT_BUYER_REQUIRED');
  need(typeof runtimeDirectory === 'string' && resolve(runtimeDirectory) === runtimeDirectory,
    'UNSTRUCTURED_NATIVE_RUNTIME_REQUIRED');
  const provider = buyer ? createPartitionEditionProvider(buyer, { workspaceId, inboxDirectory }) : null;
  let cached = null;
  const clear = () => { cached = null; };
  const dossierMetadata = id => typeof dossiers.getMetadata === 'function' ?
    dossiers.getMetadata(id) : dossiers.get(id);

  async function sourcePurchases() {
    if (!buyer) return {items:[],warnings:[]};
    const items = [], warnings = [];
    if (inboxDirectory !== undefined) {
      const result = await buyer.inbox(inboxDirectory).list();
      need(Array.isArray(result.native?.jobs), 'UNSTRUCTURED_ORIGINAL_INBOX_LIST_INVALID');
      for (const job of result.native.jobs) {
        const profileId = sourceRoute(job.operation);
        if (!profileId) {
          if (job.state === 'REVIEW_REQUIRED') warnings.push({id:job.id,error:job.lastError?.code ?? 'ORIGINAL_INBOX_REVIEW_REQUIRED'});
          continue;
        }
        need(HEX.test(job.id) && job.id === digest(job.operation.intentId),
          'UNSTRUCTURED_ORIGINAL_INBOX_LIST_INVALID');
        items.push({id:'u_'+job.id,intentId:job.operation.intentId,profileId,createdAt:job.createdAt,
          configurationSha256:job.configSha256,state:job.state,
          outputStatus:job.outcome?.responseFile?.status ?? 'NOT_SAVED',
          paymentStatus:job.outcome?.status ?? null});
      }
    } else {
      for await (const operation of buyer.list()) {
        let meta, raw, config;
        try {
          meta = await readJson(join(operation.directory,'operation.json'));
          raw = await readBytes(operation.configPath);
          need(digest(raw) === meta.configSha256, 'UNSTRUCTURED_ORIGINAL_CONFIGURATION_CHANGED');
          config = parseJson(raw);
        } catch (error) {
          warnings.push({id:'u_'+digest(operation.intentId),error:error.code ?? 'ORIGINAL_BUYER_REVIEW_REQUIRED'});
          continue;
        }
        const profileId = sourceRoute(config.operation);
        if (!profileId) continue;
        need(config.operation.intentId === operation.intentId && meta.intentId === operation.intentId,
          'UNSTRUCTURED_ORIGINAL_OPERATION_CHANGED');
        items.push({id:'u_'+digest(operation.intentId),intentId:operation.intentId,profileId,
          createdAt:meta.createdAt,configurationSha256:meta.configSha256,state:meta.state,
          outputStatus:'OPEN_ORIGINAL_RESULT',paymentStatus:null});
      }
    }
    items.sort((a,b)=>a.id.localeCompare(b.id));
    return {items,warnings};
  }
  async function resolvePurchase(id) {
    need(provider && ID.test(id), 'UNSTRUCTURED_BUYER_SOURCE_NOT_CONFIGURED');
    const row = (await sourcePurchases()).items.find(item=>item.id===id);
    need(row, 'UNSTRUCTURED_PURCHASE_NOT_FOUND');
    return row;
  }
  async function capture(dossierId, selection) {
    selection = selected(selection);
    const dossier = await dossierMetadata(dossierId);
    let envelope, retained = null;
    if (selection.purchaseId) {
      const purchase = await resolvePurchase(selection.purchaseId);
      envelope = await provider.envelope(purchase.intentId);
    } else {
      const edition = dossier.editions.find(row=>row.id===selection.editionId);
      need(edition?.mode === 'retained' && edition.origin?.mode === 'ORIGINAL_UNSTRUCTURED_SAVED_BUYER_RESULT',
        'UNSTRUCTURED_RETAINED_EDITION_REQUIRED');
      const original = await dossiers.readRetainedEdition(dossierId, selection.editionId);
      need(original.edition.id === edition.id && original.bytes instanceof Uint8Array &&
        digest(original.bytes) === edition.raw.sha256, 'UNSTRUCTURED_RETAINED_EDITION_CHANGED');
      envelope = parseJson(original.bytes);
      retained = {id:edition.id,label:edition.label,questionId:edition.questionId,createdAt:edition.createdAt};
    }
    const checked = await verifyPartitionResearchEnvelope(envelope, {runtimeDirectory});
    const key = JSON.stringify([dossierId,selection]);
    cached = {key,dossierId,selection,checked,retained};
    return cached;
  }
  async function observed(dossierId, selection, expectedEditionSha256) {
    selection = selected(selection);
    requestedHash(expectedEditionSha256);
    const key = JSON.stringify([dossierId,selection]);
    const value = cached?.key === key ? cached : await capture(dossierId,selection);
    need(value.checked.editionSha256===expectedEditionSha256, 'UNSTRUCTURED_REVIEWED_EDITION_CHANGED');
    return value;
  }
  const publicReview = value => {
    const {checked,retained} = value, purchase=checked.envelope.originalPurchase;
    return {
      selection:copy(value.selection),editionSha256:checked.editionSha256,
      binding:copy(checked.binding),document:metadata(purchase),
      summary:copy(purchase.summary),parameters:copy(purchase.selection.parameters),
      native:copy(purchase.native),retained,warnings:copy(checked.envelope.warnings),
    };
  };
  async function list(dossierId,{after='',limit=20}={}) {
    need(typeof after==='string' && (after==='' || ID.test(after)) &&
      Number.isSafeInteger(limit) && limit>=1 && limit<=100,'UNSTRUCTURED_LIST_SELECTION_INVALID');
    const dossier=await dossierMetadata(dossierId),source=await sourcePurchases();
    const remaining=source.items.filter(item=>after==='' || item.id>after),purchases=remaining.slice(0,limit);
    const editions=dossier.editions.filter(edition=>edition.mode==='retained' &&
      edition.origin?.mode==='ORIGINAL_UNSTRUCTURED_SAVED_BUYER_RESULT').map(edition=>({
        id:edition.id,label:edition.label,questionId:edition.questionId,createdAt:edition.createdAt,
        document:copy(edition.origin.document),profileId:edition.origin.profileId,
        intentId:edition.origin.intentId,elementCount:edition.origin.elementCount ?? edition.itemCount ?? null,
      }));
    return {configured:provider!==null,workspaceId:workspaceId??null,purchases,editions,warnings:source.warnings,
      nextAfter:remaining.length>limit?purchases.at(-1).id:null,revision:dossier.revision};
  }
  async function review(dossierId,selection) {
    return publicReview(await capture(dossierId,selection));
  }
  async function elements(dossierId,{
    selection,expectedEditionSha256,offset=0,limit=25,page='',type='',query='',
  }={}) {
    need(Number.isSafeInteger(offset)&&offset>=0&&Number.isSafeInteger(limit)&&limit>=1&&limit<=100&&
      [page,type,query].every(value=>typeof value==='string')&&page.length<=100&&type.length<=200&&query.length<=2000,
    'UNSTRUCTURED_ELEMENT_FILTER_INVALID');
    const value=await observed(dossierId,selection,expectedEditionSha256),search=query.toLocaleLowerCase();
    const all=value.checked.elements.map((element,index)=>({position:index+1,element}));
    const filtered=all.filter(({element})=>(page===''||String(element.metadata.page_number??'')===page)&&
      (type===''||String(element.type??'Unspecified')===type)&&
      (search===''||element.text.toLocaleLowerCase().includes(search)));
    return {editionSha256:value.checked.editionSha256,total:all.length,filtered:filtered.length,offset,limit,
      items:filtered.slice(offset,offset+limit).map(copy),nextOffset:offset+limit<filtered.length?offset+limit:null};
  }
  async function download(dossierId,{selection,expectedEditionSha256,file}={}) {
    need(['document','response','edition'].includes(file),'UNSTRUCTURED_DOWNLOAD_SELECTION_INVALID');
    const value=await observed(dossierId,selection,expectedEditionSha256),purchase=value.checked.envelope.originalPurchase;
    let bytes,filename,contentType;
    if(file==='document') {
      bytes=value.checked.document;
      filename=safeFilename(purchase.document.filename,'original-document.bin');
      // Active document formats are always downloaded, never embedded in the operator origin.
      contentType='application/octet-stream';
    } else if(file==='response') {
      bytes=decodePartitionBytes(purchase.response,PARTITION_LIMITS.responseBytes);
      filename=safeFilename(purchase.document.filename,'document')+'.elements.json';
      contentType='application/json; charset=utf-8';
    } else {
      bytes=canonicalBytes(value.checked.envelope);
      filename=safeFilename(purchase.document.filename,'document')+'.research.json';
      contentType='application/json; charset=utf-8';
    }
    return {bytes,filename,contentType,sha256:digest(bytes)};
  }
  async function receive(dossierId,{
    selection,expectedEditionSha256,questionId,label,expectedRevision,
  }={}) {
    selection=selected(selection);
    need(selection.purchaseId!==undefined,'UNSTRUCTURED_PURCHASE_SELECTION_REQUIRED');
    requestedHash(expectedEditionSha256);
    // Fresh original bytes at mutation time; the cached read never substitutes for source reconciliation.
    const current=await capture(dossierId,selection);
    const result=await receivePartitionEnvelope(dossiers,dossierId,{
      envelope:current.checked.envelope,runtimeDirectory,questionId,label,expectedRevision,
      expectedEditionSha256,mode:'retained',
    });
    clear();
    return result;
  }
  return Object.freeze({provider,list,review,elements,download,receive,clear,
    configured:provider!==null,workspaceId:workspaceId??null});
}

// MIT — Read the maintained Valyu edition through its original workspace.
import { need, object } from '../node/store.mjs';

/**
 * Adapt an existing ValyuStore; acquisition, entitlement and store lifetime stay
 * with that original workspace. Reading never purchases, freezes or imports.
 */
export function createValyuEditionProvider(store) {
  need(store && typeof store.editionView === 'function', 'VALYU_EDITION_STORE_REQUIRED');
  return {
    async read(reference) {
      need(object(reference), 'EDITION_REFERENCE_REQUIRED');
      const editionId = reference.editionId ?? reference.id;
      need(typeof editionId === 'string' && editionId.length > 0, 'EDITION_REFERENCE_REQUIRED');
      const view = await store.editionView(editionId);
      need(object(view) && view.id === editionId && Array.isArray(view.rows), 'VALYU_EDITION_VIEW_INVALID');
      const warnings = Array.isArray(view.warnings) ? view.warnings : [];
      const issues = Array.isArray(view.issues) ? view.issues : [];
      let status;
      if (view.success === false || view.status === 'error') status = 'PROVIDER_ERROR';
      else if (view.status === 'invalid' || issues.length) status = 'PROVIDER_RESPONSE_INVALID';
      else if (!['success', 'empty'].includes(view.status)) status = 'UNAVAILABLE';
      else status = view.rows.some(row => row.contentDisposition === 'withheld') ||
        warnings.length || view.error || view.httpStatus === 206 ||
        view.summary?.providerErrorPresent === true || view.summary?.providerWarningCount > 0
        ? 'PARTIAL' : 'AVAILABLE';
      const items = view.rows.map(row => {
        need(object(row) && typeof row.occurrenceId === 'string' && row.occurrenceId.length > 0,
          'VALYU_OCCURRENCE_REQUIRED');
        const withheld = row.contentDisposition === 'withheld';
        return {
          key: row.occurrenceId, id: row.id,
          title: withheld ? 'Source access restricted' : row.title,
          url: withheld ? '' : row.url, doi: withheld ? '' : row.doi,
          description: withheld ? '' : row.description,
          content: withheld ? '' : row.content,
          publishedAt: withheld ? '' : row.publicationDate,
          authors: withheld ? [] : row.authors,
          citation: withheld ? null : row.citation,
          references: withheld ? null : row.citations?.references,
          metadata: withheld ? {} : row.raw?.metadata ?? {},
          original: withheld ? null : row.raw,
        };
      });
      return {
        status, items,
        usage: { ...view.summary?.usage,
          httpStatus: view.httpStatus ?? null,
          providerWarningCount: view.summary?.providerWarningCount ?? null,
          providerErrorPresent: view.summary?.providerErrorPresent ?? null,
          retainedResultCount: view.summary?.retainedResultCount ?? null,
          withheldResultCount: view.summary?.withheldResultCount ?? null },
        warnings,
        error: view.error ?? (issues.length ? { code: 'VALYU_RESPONSE_ISSUES', issues } : null),
        availableUntil: view.validUntil ?? null,
        retention: view.retentionMode ?? 'ORIGINAL_EDITION_ACCESS',
      };
    },
  };
}

#!/usr/bin/env node
// MIT. Operate the same original Research listener from a local command.
import {parseArgs} from 'node:util';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {ResearchWorkspaceClient,researchSummary} from './workspace-client.mjs';
import {readResearchHostFile} from './workspace-files.mjs';
import {DOCUMENT_COMMANDS,main as documentMain} from './document-workspace-cli.mjs';
import {ELIGIBILITY_COMMANDS,main as eligibilityMain} from './eligibility-cli.mjs';
import {parseJson,need,safeCode} from '../node/store.mjs';

const usage=String.raw`Research workspace client

  research-client COMMAND --connection-file /private/application-url.json --directory /original/dossier-store [OPTIONS]
  research-dossiers remote COMMAND --connection-file /private/application-url.json --directory /original/dossier-store [OPTIONS]

Read the existing workspace:
  status
  list [--offset N --limit N --snapshot SHA256]
  metadata --id DOSSIER [--revision N]
  source --id DOSSIER --edition EDITION --key ORIGINAL_KEY [--revision N]
  section --id DOSSIER --section questions|editions|selections|findings|sources|revisions
          [--revision N --offset N --limit N --question ID --query TEXT --selected true|false]
  compare --id DOSSIER --before N --after N [--section overview|added|removed|changed|questions|editions|availability|findings-added|findings-removed|findings-changed --offset N --limit N]

Write an original reviewed request from JSON:
  create --input REQUEST.json
  update|question-add|evidence|selection|finding-add --id DOSSIER --input REQUEST.json
  question-update --id DOSSIER --question QUESTION --input REQUEST.json
  finding-update --id DOSSIER --finding FINDING --input REQUEST.json
  receive --id DOSSIER --input REQUEST.json --source-file RESPONSE.json --sha256 SHA256
  reference --id DOSSIER --input REQUEST.json --source-file REFERENCE.json --sha256 SHA256
  openalex-editions
  receive-openalex --id DOSSIER --input REQUEST.json

Review and receive an original source bundle:
  bundle-preview --id DOSSIER --question QUESTION --file BUNDLE.json [--sha256 SHA256]
  import-bundle --id DOSSIER --question QUESTION --file BUNDLE.json --revision N [--sha256 SHA256]

Preview returns the exact bundle hash, current revision, source terms and findings.
Import binds those original bytes to that question in one saved revision.
Repeat the same file and question after a lost reply to recover the saved result.

Receive a completed original Object Buyer file:
  object-inputs --id DOSSIER [--after-session NAME --snapshot SHA256 --limit N]
  object-reviews --id DOSSIER [--after-review ID --limit N]
  object-review --id DOSSIER --input REVIEW_REQUEST.json
  object-prepare --id DOSSIER --input PREPARE_REQUEST.json
  pipeline-list --id DOSSIER [--after-operation ID --limit N]
  pipeline-review --id DOSSIER --operation ID

Review captures the exact saved delivery; it does not acquire, assemble or pay.
Preparation binds that review to an original managed processing operation.
Submit, monitor and receive that same operation in the existing Pipelines pane
or with the documents-* and pipelines-* commands below.

Operate original Documents and the complete managed Pipeline lifecycle:
  documents-help
  documents-list|documents-review|documents-elements|documents-receive|documents-download
  pipelines-list|pipelines-operation|pipelines-prepare|pipelines-submit|pipelines-refresh
  pipelines-cancel|pipelines-provider-jobs|pipelines-reconcile|pipelines-retain
  pipelines-review|pipelines-elements|pipelines-receive|pipelines-input|pipelines-output|pipelines-download

Run documents-help for exact JSON fields, original revisions and complete file downloads.

Operate the saved original Crossref acquisition:
  crossref-prepare --id DOSSIER --input PLAN_REQUEST.json
  crossref-list --id DOSSIER [--after-operation ID --limit N]
  crossref-review --id DOSSIER --operation ID [--section overview|dois|records|added|removed|changed|warnings --offset N --limit N]
  crossref-start --id DOSSIER --operation ID --plan-sha256 SHA256
  crossref-stop --id DOSSIER --operation ID
  crossref-receive --id DOSSIER --operation ID --input REVIEWED_RECEIVE.json

Operate full eligibility review in the same original dossier:
  eligibility-help
  eligibility-view|eligibility-queue|eligibility-review|eligibility-export
  eligibility-create|eligibility-protocol|eligibility-workset|eligibility-decide
  eligibility-resolve|eligibility-study|eligibility-apply|eligibility-impact

Run eligibility-help for original request fields, revision-pinned queues,
independent review, resolution, full exports and same-request recovery.

Review a retained correction or retraction notice:
  citation-updates --id DOSSIER [--revision N --notice ID --status all|pending|reviewed --offset N --limit N]
  citation-review --id DOSSIER --input REVIEW_REQUEST.json

The review request keeps requestId, expectedRevision and expectedFingerprint.
It saves the explicit evidence edits, finding edits and finding dispositions
in one dossier revision. Repeat the same request after a lost reply.

Retain and reopen complete original files:
  export --id DOSSIER --format json|json.gz|md|html --out NEW_FILE [--revision N]
  export-crossref --id DOSSIER --operation ID --out NEW_FILE
  export-edition --id DOSSIER --edition ID --out NEW_FILE [--revision N --sha256 SHA256]
  export-source --id DOSSIER --edition ID --key ORIGINAL_KEY --part content|record --out NEW_FILE [--revision N --sha256 SHA256]
  export-source-file --id DOSSIER --edition ID --key ORIGINAL_KEY --name ORIGINAL_NAME --sha256 SHA256 --out NEW_FILE [--revision N]
  export-compare --id DOSSIER --before N --after N --out NEW_FILE
  reopen --source-file PORTABLE_JSON_OR_GZIP --sha256 SHA256

Mutation JSON uses the original fields, including expectedRevision. Crossref
preparation keeps requestId, questionId and the reviewed expectedRevision;
receive keeps expectedRevision, expectedPlanSha256 and expectedEditionSha256.
Page zero returns the revision or snapshot required by subsequent pages.
Source and comparison pages contain compact previews and complete descriptive metadata.
Use a citation's editionId/key to inspect one original occurrence; a file also
keeps its original member name and SHA256. Downloads preserve the selected
revision and never overwrite an existing destination. Content/record exports
are declared text/JSON representations; export-edition keeps the original response bytes.
A lost write reply is reconciled through that same dossier/operation.
The private startup file is reread on every call. Closing this client leaves
the original Applications listener and saved acquisitions with their owner.
`;

const commandOptions=Object.freeze({
  status:[],list:['offset','limit','snapshot'],metadata:['id','revision'],
  source:['id','edition','key','revision'],
  section:['id','section','revision','offset','limit','question','query','selected'],
  create:['input'],update:['id','input'],'question-add':['id','input'],
  'question-update':['id','question','input'],evidence:['id','input'],selection:['id','input'],
  'finding-add':['id','input'],'finding-update':['id','finding','input'],
  compare:['id','before','after','section','offset','limit'],
  receive:['id','input','source-file','sha256'],reference:['id','input','source-file','sha256'],
  'openalex-editions':[],'receive-openalex':['id','input'],
  'bundle-preview':['id','question','file','sha256'],
  'import-bundle':['id','question','file','sha256','revision'],
  'object-inputs':['id','after-session','snapshot','limit'],
  'object-reviews':['id','after-review','limit'],'object-review':['id','input'],'object-prepare':['id','input'],
  'pipeline-list':['id','after-operation','limit'],'pipeline-review':['id','operation'],
  'crossref-prepare':['id','input'],'crossref-list':['id','after-operation','limit'],
  'crossref-review':['id','operation','section','offset','limit'],
  'crossref-start':['id','operation','plan-sha256'],'crossref-stop':['id','operation'],
  'crossref-receive':['id','operation','input'],
  'citation-updates':['id','revision','notice','status','offset','limit'],
  'citation-review':['id','input'],
  export:['id','format','out','sha256','revision'],'export-crossref':['id','operation','out','sha256'],
  'export-edition':['id','edition','out','revision','sha256'],'export-compare':['id','before','after','out','sha256'],
  'export-source':['id','edition','key','part','out','revision','sha256'],
  'export-source-file':['id','edition','key','name','out','revision','sha256'],
  reopen:['source-file','sha256'],
});
const compact=value=>value?.dossier?{...value,dossier:researchSummary(value.dossier)}:value;
const selected=value=>Object.fromEntries(Object.entries(value).filter(([,item])=>item!==undefined));
export async function main(argv=process.argv.slice(2),{output=process.stdout}={}){
  if(DOCUMENT_COMMANDS.includes(argv[0]))return documentMain(argv,{output});
  if(ELIGIBILITY_COMMANDS.includes(argv[0]))return eligibilityMain(argv,{output});
  const [command,...args]=argv;
  if(!command||['help','--help','-h'].includes(command)){output.write(usage);return;}
  need(Object.hasOwn(commandOptions,command),'COMMAND_UNKNOWN');
  const fields=['connection-file','directory','timeout-ms',...commandOptions[command]];
  const {values,tokens}=parseArgs({args,options:Object.fromEntries(fields.map(key=>[key,{type:'string'}])),strict:true,tokens:true});
