    if(await existing(path))selected.add(path);
    else {
      need(optional,'WORKSPACE_RECOVERY_DEPENDENCY_MISSING');missing.add(path);
      const parent=dirname(path);
      if(await existing(parent)) {
        await privateDirectory(parent);parentDirectories.add(parent);
      }
    }
  }
  async function configuration(cfg) {
    const current=execution(cfg);
    need(['actor','service','ledger','policy','python'].every(k=>current.owner[k]===owner[k])&&
      cfg.signerModule===workspace.config.signerModule&&cfg.evidenceDir===workspace.config.evidenceDir&&
      cfg.trustedPayer===workspace.config.trustedPayer,'WORKSPACE_RECOVERY_INBOX_USES_DIFFERENT_OPERATOR');
    await dependency(current.op.bodyFile);
    await dependency(current.op.ticketFile);
    await dependency(current.download?.destination,{optional:true});
  }
  await configuration(workspace.config);
  if(typeof workspace.manifest.sourceConfig==='string'&&inside(stateRoot,workspace.manifest.sourceConfig))
    await dependency(workspace.manifest.sourceConfig,{optional:true});
  for(const root of [...new Set(inboxes)].sort()) {
    requireInside(root);
    const queue=await openQueue(root),jobs=await queue.list();selected.add(root);
    need(jobs.length<=MAX_FILES,'WORKSPACE_RECOVERY_INBOX_TOO_LARGE');
    for(const job of jobs) {
      need(job.state!=='REVIEW_REQUIRED','WORKSPACE_RECOVERY_INBOX_INVALID');
      await configuration(await config(join(root,'jobs',job.id,'execution.json')));
      await dependency(job.outcome?.responseFile?.partialPath,{optional:true});
      const dependencies=job.dependencies;
      for(const name of ['signer','policy']) {
        const observed=await digest(dependencies[name].path);
        need(observed.sha256===dependencies[name].sha256&&observed.size===dependencies[name].bytes,
          'WORKSPACE_RECOVERY_ORIGINAL_DEPENDENCY_CHANGED');
      }
    }
    summaries.push({root,jobs:jobs.map(job=>({id:job.id,intentId:job.operation.intentId,state:job.state,
      configSha256:job.configSha256,attemptId:job.attempt?.id??null,
      finality:job.finalization?.lastFinalized?.result?.receipt_ref??
        job.finalization?.result?.receipt_ref??null}))});
  }
  for(const path of include)await dependency(path);
  for(const path of optionalInclude)await dependency(path,{optional:true});
  const paths=[...selected].sort().filter((path,_i,all)=>!all.some(other=>other!==path&&inside(other,path)));
  for(const path of paths) {
    const st=await lstat(path);
    if(st.isDirectory())await privateDirectory(path);
    else {const {handle}=await regular(path);await handle.close();}
  }
  const runtime=[owner.python,workspace.manifest.sourceCli,workspace.manifest.signer.signerProvider]
    .filter(path=>typeof path==='string');
  return {schema:SCHEMA,stateRoot,directory,inboxes:summaries,include:[...new Set(include)].sort(),
    selected:paths,missing:[...missing].sort(),parentDirectories:[...parentDirectories].sort(),
    network:workspace.manifest.network,payer:workspace.manifest.payer,
    walletEnvironment:workspace.manifest.signer.secretEnv??null,
    ledger:owner.ledger,policy:owner.policy,keys:join(directory,'operator-keys.json'),python:owner.python,
    runtime:runtime.map(path=>({path,retained:false})),
    walletEnvironmentExported:false,restoreMode:'ORIGINAL_CANONICAL_STATE_ROOT',
    ...(optionalInclude.length?{optionalInclude:[...new Set(optionalInclude)].sort()}:{})};
}

const originalOperators=plan=>[plan,...(plan.operators??[])];
async function inventory(plan) {
  const ledgers=new Set(originalOperators(plan).map(operator=>operator.ledger));
  const excluded=new Set([...ledgers].flatMap(path=>[path+'-wal',path+'-shm']));
  const entries=new Map();let total=0;
  async function walk(path,depth=0) {
    if(excluded.has(path))return;
    const rel=relative(plan.stateRoot,path).split(sep).join('/');
    member(rel,{root:true});
    const st=await lstat(path);
    need(privateInfo(st)&&(st.isFile()||st.isDirectory())&&depth<=15,
      'WORKSPACE_RECOVERY_UNSAFE_SOURCE');
    need(entries.size<MAX_FILES,'WORKSPACE_RECOVERY_FILE_LIMIT');
    if(st.isDirectory()) {
      need(await realpath(path)===path,'WORKSPACE_RECOVERY_SYMLINK_PARENT');
      entries.set(rel,{path:rel,kind:'directory',stamp:stamp(st)});
      for(const name of (await readdir(path)).sort())await walk(join(path,name),depth+1);
    } else {
      need(st.nlink===1&&st.size<=MAX_FILE,'WORKSPACE_RECOVERY_UNSAFE_SOURCE');
      total+=st.size;need(total<=MAX_BYTES,'WORKSPACE_RECOVERY_SIZE_LIMIT');
      if(plan.schema===COLLECTION&&path.endsWith('/reservations.sqlite'))need(ledgers.has(path),
        'WORKSPACE_RECOVERY_UNSELECTED_OPERATOR_LEDGER');
      entries.set(rel,{path:rel,kind:ledgers.has(path)?'ledger':'file',
        ...(ledgers.has(path)?{identity:{dev:st.dev,ino:st.ino}}:{stamp:stamp(st)})});
    }
  }
  for(const path of plan.selected)await walk(path);
  for(const path of plan.parentDirectories) {
    const rel=relative(plan.stateRoot,path).split(sep).join('/');
    if(!entries.has(rel))entries.set(rel,{path:rel,kind:'directory',stamp:stamp(await privateDirectory(path))});
  }
  for(const path of plan.missing)need(!(await existing(path)),'WORKSPACE_RECOVERY_SOURCE_CHANGED');
  return [...entries.values()].sort((a,b)=>a.path.localeCompare(b.path));
}

async function startLedger(mode,{python,database,policy,keys,destination,signal}) {
  need(!signal?.aborted,'WORKSPACE_RECOVERY_INTERRUPTED');
  await checkPython(python);
  const stored=(await readJson(keys,16384)).value;
  need(stored.schema==='stellar-forge.sf88.operator-workspace.v1'&&object(stored.keys)&&
    Object.keys(stored.keys).length===3&&KEY_NAMES.every(k=>typeof stored.keys[k]==='string'),
    'WORKSPACE_RECOVERY_KEYS_INVALID');
  let identity;
  if(mode==='snapshot') {
    const original=await regular(database);
    identity={dev:original.st.dev,ino:original.st.ino};await original.handle.close();
  }
  need(!signal?.aborted,'WORKSPACE_RECOVERY_INTERRUPTED');
  const child=spawn(python,['-I','-B',LEDGER,mode,database,policy,...(destination?[destination]:[])],
    {shell:false,env:{LANG:'C.UTF-8',LC_ALL:'C.UTF-8'},stdio:['pipe','pipe','ignore']});
  let output='',first=false,closed=false,failure,resolveReady,rejectReady,resolveDone,rejectDone;
  const ready=new Promise((accept,reject)=>{resolveReady=accept;rejectReady=reject;});
  const done=new Promise((accept,reject)=>{resolveDone=accept;rejectDone=reject;});
  done.catch(()=>{});
  const fail=()=>{
    failure=error('WORKSPACE_RECOVERY_LEDGER_FAILED');
    rejectReady(failure);
  };
  const timer=setTimeout(()=>{child.kill('SIGKILL');fail();},180000);
  const abort=()=>{child.kill('SIGKILL');fail();};
  signal?.addEventListener('abort',abort,{once:true});
  child.once('error',fail);child.stdin.once('error',fail);
  child.stdout.on('data',chunk=>{
    output+=chunk;
    if(output.length>65536){child.kill('SIGKILL');fail();return;}
    const end=output.indexOf('\n');
    if(end<0||first)return;
    first=true;
    try {
      const value=JSON.parse(output.slice(0,end));
      need(value.status===(mode==='snapshot'?'CAPTURE_LOCKED':'LEDGER_VERIFIED')&&
        value.checkpoint?.outcome==='JOURNAL_CONSISTENT','WORKSPACE_RECOVERY_LEDGER_FAILED');
      resolveReady(value.checkpoint);
    } catch{child.kill('SIGKILL');fail();}
  });
  child.once('close',code=>{
    closed=true;clearTimeout(timer);signal?.removeEventListener('abort',abort);
    if(code===0&&first&&!failure)resolveDone();
    else {fail();rejectDone(failure);}
  });
  child.stdin.write(JSON.stringify({keys:stored.keys,...(identity?{identity}:{})})+'\n');
  if(mode==='verify')child.stdin.end();
  try {
    const checkpoint=await ready;
    if(mode==='verify')await done;
    return {checkpoint,
      async release(){need(!closed,'WORKSPACE_RECOVERY_LEDGER_LOCK_LOST');child.stdin.end('release\n');await done;},
      async stop(){if(!closed)child.kill('SIGKILL');await done.catch(()=>{});}};
  } catch(e){if(!closed)child.kill('SIGKILL');await done.catch(()=>{});throw e;}
}

async function cryptography(args,passEnv,environment,signal) {
  need(!signal?.aborted,'WORKSPACE_RECOVERY_INTERRUPTED');
  need(typeof passEnv==='string'&&/^[A-Z][A-Z0-9_]{4,63}$/.test(passEnv),
    'WORKSPACE_RECOVERY_PASSPHRASE_NAME_INVALID');
  need(passEnv!=='STELLAR_SECRET'&&!KEY_NAMES.includes(passEnv),
    'WORKSPACE_RECOVERY_SEPARATE_PASSPHRASE_REQUIRED');
  const passphrase=environment[passEnv];
  need(typeof passphrase==='string'&&Buffer.byteLength(passphrase)>=16&&
    Buffer.byteLength(passphrase)<=65536,'WORKSPACE_RECOVERY_PASSPHRASE_REQUIRED');
  return await new Promise((accept,reject)=>{
    const child=spawn(process.execPath,[CRYPTO,...args,'--pass-env',passEnv],
      {shell:false,env:{LANG:'C.UTF-8',LC_ALL:'C.UTF-8',[passEnv]:passphrase},
        stdio:['ignore','pipe','ignore']});
    let output='',settled=false;
    const finish=(problem,result)=>{
      if(settled)return;settled=true;clearTimeout(timer);signal?.removeEventListener('abort',abort);
      problem?reject(problem):accept(result);
    };
    const abort=()=>{child.kill('SIGKILL');};
    signal?.addEventListener('abort',abort,{once:true});
    const timer=setTimeout(()=>{child.kill('SIGKILL');finish(error('WORKSPACE_RECOVERY_ARCHIVE_TIMEOUT'));},1800000);
    child.once('error',()=>finish(error('WORKSPACE_RECOVERY_ARCHIVE_START_FAILED')));
    child.stdout.on('data',chunk=>{
      output+=chunk;
      if(output.length>65536){child.kill('SIGKILL');finish(error('WORKSPACE_RECOVERY_ARCHIVE_RESULT_INVALID'));}
    });
    child.once('close',code=>{
      if(code!==0)return finish(error('WORKSPACE_RECOVERY_ARCHIVE_FAILED'));
      try {finish(null,JSON.parse(output));}catch{finish(error('WORKSPACE_RECOVERY_ARCHIVE_RESULT_INVALID'));}
    });
  });
}
async function stagedFiles(root,signal) {
  const files=[];let total=0;
  async function walk(path,rel='') {
    need(files.length<MAX_FILES,'WORKSPACE_RECOVERY_FILE_LIMIT');
    const st=await lstat(path);
    need(privateInfo(st)&&!st.isSymbolicLink(),'WORKSPACE_RECOVERY_STAGED_FILE_INVALID');
    if(st.isDirectory()) {
      files.push({path:rel,kind:'directory'});
      for(const name of (await readdir(path)).sort())await walk(join(path,name),rel?rel+'/'+name:name);
    } else {
      const observed=await digest(path,undefined,signal);total+=observed.size;
      need(total<=MAX_BYTES,'WORKSPACE_RECOVERY_SIZE_LIMIT');
      files.push({path:rel,kind:'file',...observed});
    }
  }
  await walk(root);
  return files.sort((a,b)=>a.path.localeCompare(b.path));
}
function result(record,recordSha256) {
  return {schema:record.schema,recordSha256,createdAt:record.createdAt,stateRoot:record.plan.stateRoot,
    directory:record.plan.directory,network:record.plan.network,payer:record.plan.payer,
    files:record.files.filter(f=>f.kind==='file').length,
    bytes:record.files.reduce((n,f)=>n+(f.size??0),0),checkpoint:record.checkpoint,
    inboxes:record.plan.inboxes.map(i=>({root:i.root,jobs:i.jobs.length})),
    runtime:record.plan.runtime,walletEnvironmentExported:false,
    ...(record.schema===COLLECTION?{operators:originalOperators(record.plan).map(operator=>({
      directory:operator.directory,ledger:operator.ledger,network:operator.network,payer:operator.payer,
      checkpoint:record.checkpoints.find(item=>item.directory===operator.directory).checkpoint})),
      ...(record.application?{application:record.application}:{})}: {})};
}

/** The caller stops original writers first; the database lock and full source
 * comparison additionally reject a capture that changes under this operation. */
export async function snapshotWorkspaceRecovery(options,{environment=process.env,signal,
  prepareSnapshot,onProgress=()=>{}}={}) {
  need(!signal?.aborted,'WORKSPACE_RECOVERY_INTERRUPTED');
  need(options.quiesced===true,'WORKSPACE_RECOVERY_QUIESCED_SOURCE_REQUIRED');
  const plan=await inspectWorkspaceRecovery(options);
  need(originalOperators(plan).every(operator=>(options.passEnv??'SF88_BACKUP_PASSPHRASE')!==operator.walletEnvironment),
    'WORKSPACE_RECOVERY_SEPARATE_PASSPHRASE_REQUIRED');
  const output=absolute(options.output);
  need(!inside(plan.stateRoot,output)&&!inside(output,plan.stateRoot),
    'WORKSPACE_RECOVERY_ARCHIVE_OVERLAPS_STATE');
  need(!(await existing(output)),'WORKSPACE_RECOVERY_ARCHIVE_EXISTS');
  need(await realpath(dirname(output))===dirname(output),'WORKSPACE_RECOVERY_OUTPUT_PARENT_INVALID');
  const temporary=await mkdtemp(join(dirname(output),'.sf88-capture-'));
  const staged=join(temporary,'state');await mkdir(staged,{mode:0o700});
  const holders=[],checkpoints=[];let outputPlaceholder;
  try {
    for(const operator of originalOperators(plan).sort((a,b)=>a.ledger.localeCompare(b.ledger))) {
      const database=join(staged,relative(plan.stateRoot,operator.ledger));
      await mkdir(dirname(database),{recursive:true,mode:0o700});
      const holder=await startLedger('snapshot',{python:operator.python,database:operator.ledger,
        policy:operator.policy,keys:operator.keys,destination:database,signal});
      holders.push(holder);checkpoints.push({directory:operator.directory,ledger:operator.ledger,checkpoint:holder.checkpoint});
      onProgress({stage:'LEDGER_CAPTURED',directory:operator.directory,checkpoint:holder.checkpoint});
    }
    const before=await inventory(plan);
    for(const entry of before) {
      const destination=join(staged,entry.path);
      if(entry.kind==='directory')await mkdir(destination,{recursive:true,mode:0o700});
      else if(entry.kind!=='ledger') {
        await mkdir(dirname(destination),{recursive:true,mode:0o700});
        const source=join(plan.stateRoot,entry.path);
        need(same(entry.stamp,stamp(await lstat(source))),'WORKSPACE_RECOVERY_SOURCE_CHANGED');
        await digest(source,destination,signal);
      }
    }
    need(same(before,await inventory(plan)),'WORKSPACE_RECOVERY_SOURCE_CHANGED');
    need(same(plan,await inspectWorkspaceRecovery(options)),'WORKSPACE_RECOVERY_SOURCE_CHANGED');
    for(const holder of holders)await holder.release();holders.length=0;
    for(const operator of originalOperators(plan)) {
      const verified=await startLedger('verify',{python:operator.python,
        database:join(staged,relative(plan.stateRoot,operator.ledger)),
        policy:join(staged,relative(plan.stateRoot,operator.policy)),
        keys:join(staged,relative(plan.stateRoot,operator.keys)),signal});
      need(same(checkpoints.find(item=>item.directory===operator.directory).checkpoint,verified.checkpoint),
        'WORKSPACE_RECOVERY_CHECKPOINT_MISMATCH');
    }
    let application;
    if(prepareSnapshot!==undefined) {
      need(plan.schema===COLLECTION&&typeof prepareSnapshot==='function','WORKSPACE_RECOVERY_CAPTURE_HOOK_INVALID');
      application=await prepareSnapshot({staged,stateRoot:plan.stateRoot,plan});
      need(object(application)&&Buffer.byteLength(JSON.stringify(application))<=1024*1024,
        'WORKSPACE_RECOVERY_APPLICATION_RECORD_INVALID');
    }
    const files=await stagedFiles(staged,signal);
    for(const entry of [...files].reverse())if(entry.kind==='directory')await syncDirectory(join(staged,entry.path));
    const checkpoint=checkpoints.find(item=>item.directory===plan.directory).checkpoint;
    const record={schema:plan.schema,createdAt:new Date().toISOString(),plan,checkpoint,files,
      ...(plan.schema===COLLECTION?{checkpoints,...(application?{application}:{})}:{})};
    onProgress({stage:'ENCRYPTING',operators:checkpoints.length,files:files.length});
    const recordPath=join(temporary,'record.json');await save(recordPath,record);
    const planPath=join(temporary,'plan.json');
    await save(planPath,{schema:'stellar-forge.merchant-recovery-plan.v1',
      roots:[{name:'state',path:staged},{name:'record',path:recordPath}]});
    const encryptedPath=join(temporary,'encrypted');
    const encrypted=await cryptography(['snapshot','--plan',planPath,'--out',encryptedPath,'--quiesced'],
      options.passEnv??'SF88_BACKUP_PASSPHRASE',environment,signal);
    need(encrypted.status==='SNAPSHOT_CREATED','WORKSPACE_RECOVERY_ARCHIVE_RESULT_INVALID');
    need(!signal?.aborted,'WORKSPACE_RECOVERY_INTERRUPTED');
    await mkdir(output,{mode:0o700});outputPlaceholder=await lstat(output);
    await rename(encryptedPath,output);outputPlaceholder=null;await syncDirectory(dirname(output));
    return {status:'BUYER_STATE_BACKUP_CREATED',bundle:output,
      ...result(record,sha(Buffer.from(json(record))))};
  } finally {
    for(const holder of holders)await holder.stop();
    if(outputPlaceholder) {
      const current=await existing(output);
      if(current?.ino===outputPlaceholder.ino&&current?.dev===outputPlaceholder.dev&&
        (await readdir(output)).length===0)await rm(output,{recursive:true});
    }
    await rm(temporary,{recursive:true,force:true});
  }
}

function validateRecord(record) {
  need(object(record)&&[SCHEMA,COLLECTION].includes(record.schema)&&object(record.plan)&&record.plan.schema===record.schema&&
    Array.isArray(record.files)&&record.files.length<=MAX_FILES&&Array.isArray(record.plan.inboxes)&&
    Array.isArray(record.plan.runtime)&&record.checkpoint?.outcome==='JOURNAL_CONSISTENT',
    'WORKSPACE_RECOVERY_RECORD_INVALID');
  const p=record.plan;absolute(p.stateRoot);
  if(record.schema===COLLECTION)need(Array.isArray(p.operators)&&p.operators.length<=63&&
    Array.isArray(record.checkpoints)&&record.checkpoints.length===p.operators.length+1&&
    (record.application===undefined||object(record.application)&&
      Buffer.byteLength(JSON.stringify(record.application))<=1024*1024),'WORKSPACE_RECOVERY_RECORD_INVALID');
  else need(p.operators===undefined&&record.checkpoints===undefined&&record.application===undefined,
    'WORKSPACE_RECOVERY_RECORD_INVALID');
  const operatorNames=new Set();
  for(const operator of originalOperators(p)) {
    need(!operatorNames.has(operator.directory)&&Array.isArray(operator.inboxes)&&
      (operator===p||operator.schema===SCHEMA&&operator.operators===undefined&&operator.stateRoot===p.stateRoot),
      'WORKSPACE_RECOVERY_RECORD_INVALID');
    operatorNames.add(operator.directory);
    for(const path of [operator.directory,operator.ledger,operator.policy,operator.keys,...operator.inboxes.map(i=>i.root)]) {
      absolute(path);need(inside(p.stateRoot,path),'WORKSPACE_RECOVERY_RECORD_PATH_INVALID');
    }
    need(operator.ledger===join(operator.directory,'reservations.sqlite')&&operator.policy===join(operator.directory,'policy.json')&&
      operator.keys===join(operator.directory,'operator-keys.json'),'WORKSPACE_RECOVERY_RECORD_PATH_INVALID');
    if(record.schema===COLLECTION) {
      const matches=record.checkpoints.filter(item=>object(item)&&item.directory===operator.directory);
      need(matches.length===1&&matches[0].ledger===operator.ledger&&matches[0].checkpoint?.outcome==='JOURNAL_CONSISTENT',
        'WORKSPACE_RECOVERY_RECORD_INVALID');
    }
  }
  if(record.schema===COLLECTION)need(same(record.checkpoint,record.checkpoints.find(item=>item.directory===p.directory).checkpoint),
    'WORKSPACE_RECOVERY_RECORD_INVALID');
  const names=new Set();let bytes=0;
  for(const f of record.files) {
    member(f.path,{root:f.kind==='directory'});
    need(!names.has(f.path)&&['file','directory'].includes(f.kind),'WORKSPACE_RECOVERY_RECORD_INVALID');
    names.add(f.path);
    if(f.kind==='file') {
      need(Number.isSafeInteger(f.size)&&f.size>=0&&f.size<=MAX_FILE&&
        /^[a-f0-9]{64}$/.test(f.sha256??''),'WORKSPACE_RECOVERY_RECORD_INVALID');
      bytes+=f.size;
    }
  }
  need(bytes<=MAX_BYTES&&record.files.some(f=>f.path===''&&f.kind==='directory'),
    'WORKSPACE_RECOVERY_RECORD_INVALID');
  return record;
}
async function openBackup(options,{environment=process.env,signal,inspectSnapshot,onProgress=()=>{}}={}) {
  need(!signal?.aborted,'WORKSPACE_RECOVERY_INTERRUPTED');
  const bundle=absolute(options.bundle);await privateDirectory(bundle);
  const temporary=await mkdtemp(join(tmpdir(),'.sf88-open-'));
  const extracted=join(temporary,'contents');
  try {
    await cryptography(['restore','--bundle',bundle,'--out',extracted],
      options.passEnv??'SF88_BACKUP_PASSPHRASE',environment,signal);
    const {raw,value}=await readJson(join(extracted,'record'));
    const record=validateRecord(value),recordSha256=sha(raw),staged=join(extracted,'state');
    if(options.expected!==undefined)need(options.expected===recordSha256,
      'WORKSPACE_RECOVERY_SELECTED_BACKUP_CHANGED');
    need(same(record.files,await stagedFiles(staged,signal)),'WORKSPACE_RECOVERY_CONTENT_MISMATCH');
    const map=path=>join(staged,relative(record.plan.stateRoot,path));
    for(const operator of originalOperators(record.plan)) {
      const original=await openWorkspace(['--dir',operator.directory],
        {accounting:true,storageDirectory:map(operator.directory)});
      const cfg=original.config;
      const {owner,op}=execution(cfg);
      need(op.expect.network===operator.network&&cfg.trustedPayer===operator.payer&&
        owner.ledger===operator.ledger&&owner.policy===operator.policy,
        'WORKSPACE_RECOVERY_ORIGINAL_BINDING_INVALID');
      const checked=await startLedger('verify',{python:options.python??'/usr/bin/python3',
        database:map(operator.ledger),policy:map(operator.policy),keys:map(operator.keys),signal});
      const expected=record.schema===COLLECTION?record.checkpoints.find(item=>item.directory===operator.directory).checkpoint:record.checkpoint;
      need(same(expected,checked.checkpoint),'WORKSPACE_RECOVERY_CHECKPOINT_MISMATCH');
      onProgress({stage:'LEDGER_VERIFIED',directory:operator.directory,checkpoint:checked.checkpoint});
    }
    if(inspectSnapshot!==undefined) {
      need(typeof inspectSnapshot==='function','WORKSPACE_RECOVERY_CAPTURE_HOOK_INVALID');
      await inspectSnapshot({staged,record,map});
    }
    return {temporary,staged,record,recordSha256};
  } catch(e){await rm(temporary,{recursive:true,force:true});throw e;}
}
export async function verifyWorkspaceRecovery(options,context) {
  const opened=await openBackup(options,context);
  try {return {status:'BUYER_STATE_BACKUP_VERIFIED',...result(opened.record,opened.recordSha256)};}
  finally {await rm(opened.temporary,{recursive:true,force:true});}
}
async function copyState(from,to,files,signal) {
  for(const file of files) {
    const target=join(to,file.path);
    if(file.kind==='directory')await mkdir(target,{recursive:true,mode:0o700});
    else {
      await mkdir(dirname(target),{recursive:true,mode:0o700});
      const observed=await digest(join(from,file.path),target,signal);
      need(observed.sha256===file.sha256&&observed.size===file.size,'WORKSPACE_RECOVERY_CONTENT_MISMATCH');
    }
  }
  for(const file of [...files].reverse())if(file.kind==='directory')await syncDirectory(join(to,file.path));
}
/** Publish a complete authenticated state directory. Existing populated state
 * is never replaced or merged. Original request/config/key bytes are unchanged. */
export async function restoreWorkspaceRecovery(options,context) {
  const opened=await openBackup(options,context);
  let adjacent,published;
  try {
    const {record}=opened,target=record.plan.stateRoot,parent=dirname(target);
    need(!inside(target,absolute(options.bundle))&&!inside(absolute(options.bundle),target),
      'WORKSPACE_RECOVERY_ARCHIVE_OVERLAPS_STATE');
    need(await realpath(parent)===parent,'WORKSPACE_RECOVERY_RESTORE_PARENT_REQUIRED');
    const old=await existing(target);
    if(old) {
      await privateDirectory(target);
      need((await readdir(target)).length===0,'WORKSPACE_RECOVERY_TARGET_NOT_EMPTY');
    }
    let staged=opened.staged;
    if((await lstat(staged)).dev!==(await lstat(parent)).dev) {
      adjacent=await mkdtemp(join(parent,'.sf88-restore-'));
      await copyState(staged,adjacent,record.files,context?.signal);staged=adjacent;
    }
    need(!context?.signal?.aborted,'WORKSPACE_RECOVERY_INTERRUPTED');
    // Reserving an empty private destination permits an interrupted publication
    // to restart. POSIX rename refuses a concurrently populated directory.
    await mkdir(target,{mode:0o700}).catch(e=>{if(e.code!=='EEXIST')throw e;});
    await privateDirectory(target);
    need((await readdir(target)).length===0,'WORKSPACE_RECOVERY_TARGET_NOT_EMPTY');
    await rename(staged,target);
    const collection=record.schema===COLLECTION;
    const diagnostic=failure=>/^[A-Z0-9_]{1,120}$/.test(failure?.code??'')?failure.code:'WORKSPACE_RECOVERY_REOPEN_FAILED';
    published={status:'BUYER_STATE_RESTORED',...result(record,opened.recordSha256),
      executionStarted:false,originalStateRetained:true,
      ...(collection?{nativeReopenErrors:[],publicationSyncError:null,cleanupErrors:[]}: {})};
    try {await syncDirectory(parent);}catch(failure) {
      if(!collection)throw failure;published.publicationSyncError=diagnostic(failure);
    }
    // Reopen every original operator. Preserve the published collection result
    // if a local runtime check fails after the complete target became visible.
    for(const operator of originalOperators(record.plan)) {
      try {await openWorkspace(['--dir',operator.directory],{accounting:true});}
      catch(failure) {if(!collection)throw failure;
        published.nativeReopenErrors.push({directory:operator.directory,code:diagnostic(failure)});}
    }
    for(const inbox of originalOperators(record.plan).flatMap(operator=>operator.inboxes)) {
      try {
        const jobs=await (await openQueue(inbox.root)).list();
        need(jobs.length===inbox.jobs.length&&jobs.every(j=>j.state!=='REVIEW_REQUIRED'),
          'WORKSPACE_RECOVERY_REOPEN_FAILED');
      } catch(failure) {if(!collection)throw failure;
        published.nativeReopenErrors.push({directory:inbox.root,code:diagnostic(failure)});}
    }
    return published;
  } finally {
    for(const path of [adjacent,opened.temporary].filter(Boolean)) {
      try {await rm(path,{recursive:true,force:true});}
      catch(failure) {
        if(published?.schema!==COLLECTION)throw failure;
        published.cleanupErrors.push({directory:path,code:/^[A-Z0-9_]{1,120}$/.test(failure?.code??'')?
          failure.code:'WORKSPACE_RECOVERY_CLEANUP_FAILED'});
      }
    }
  }
}

export async function workspaceRecoveryCommand(command,args,context) {
  const opt={inboxes:[],include:[]};
  const names={'--dir':'directory','--state-root':'stateRoot','--inbox':'inboxes','--include':'include','--operator':'operators',
    '--out':'output','--bundle':'bundle','--pass-env':'passEnv','--python':'python','--expect':'expected'};
  for(let i=0;i<args.length;i++) {
    const flag=args[i];
    if(flag==='--quiesced'){need(!opt.quiesced,'WORKSPACE_RECOVERY_ARGUMENT_INVALID');opt.quiesced=true;continue;}
    need(Object.hasOwn(names,flag)&&typeof args[i+1]==='string'&&args[i+1].length>0,
      'WORKSPACE_RECOVERY_ARGUMENT_INVALID');
    const key=names[flag],value=args[++i];
    if(key==='operators')opt.operators??=[];
    if(Array.isArray(opt[key]))opt[key].push(value);
    else {need(opt[key]===undefined,'WORKSPACE_RECOVERY_ARGUMENT_INVALID');opt[key]=value;}
  }
  const allowed={
    '--inspect-workspace-backup':['directory','stateRoot','inboxes','include','operators'],
    '--backup-workspace':['directory','stateRoot','inboxes','include','operators','output','passEnv','quiesced'],
    '--verify-workspace-backup':['bundle','passEnv','python','expected','inboxes','include'],
    '--restore-workspace':['bundle','passEnv','python','expected','inboxes','include'],
  }[command];
  need(allowed&&Object.keys(opt).every(k=>allowed.includes(k)),'WORKSPACE_RECOVERY_ARGUMENT_INVALID');
  if(command==='--inspect-workspace-backup')return inspectWorkspaceRecovery(opt);
  if(command==='--backup-workspace')return snapshotWorkspaceRecovery(opt,context);
  need(opt.inboxes.length===0&&opt.include.length===0,'WORKSPACE_RECOVERY_ARGUMENT_INVALID');
  if(command==='--verify-workspace-backup')return verifyWorkspaceRecovery(opt,context);
  return restoreWorkspaceRecovery(opt,context);
}

// MIT. Private operator setup for the original SF88 -> SF81 -> SF36 buyer.
import { spawn } from 'node:child_process';
import { randomBytes, createHash } from 'node:crypto';
import { constants } from 'node:fs';
import { access, lstat, mkdir, open, realpath, rm, stat, writeFile } from 'node:fs/promises';
import { basename, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { abs, buyerTransport, config, execution, need, operation, operator, requestTimeoutMs, InputError } from './config.mjs';
import { resolveBuyerProxy } from '../sf31-buyer-client/public-transport.mjs';
import { checkOperatorChannel, operatorApprovalEnvironment } from '../sf81-buyer-operator-bridge/bridge.mjs';
import { loadOperationTicket, operationTicketView } from './operation-ticket.mjs';
import { NETWORKS } from '../sf86-rpc-transfer-reconcile/terms.mjs';
import { readRequestBody } from './request-body.mjs';
import { acquireInitialization, initializationDirectory, optionalInitializationBytes,
  retainInitializationFile, retainInitializationRecord, verifyInitializationFile } from './initialization.mjs';

const SCHEMA = 'stellar-forge.sf88.operator-workspace.v1';
const KEY_NAMES = ['SF36_CONSENT_KEY_B64', 'SF36_AUDIT_KEY_B64', 'SF36_OPERATOR_KEY_B64'];
const MAX_ATOMIC = 9223372036854775807n; // Original SF36 SQLite policy limit.
const cliPath = fileURLToPath(new URL('./cli.mjs', import.meta.url));
const governorPath = fileURLToPath(new URL('../sf36-spend-governor/', import.meta.url));
const signerUrl = new URL('./native-signer.mjs', import.meta.url).href;
const schemaObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const json = value => JSON.stringify(value, null, 2) + '\n';

function amount(value, code) {
  need(typeof value === 'string' && /^[1-9][0-9]{0,18}$/.test(value) &&
    BigInt(value) <= MAX_ATOMIC, code);
  return value;
}
function options(args, allowed) {
  need(args.length % 2 === 0, 'WORKSPACE_ARGUMENT_VALUE_REQUIRED');
  const result = {};
  for (let i = 0; i < args.length; i += 2) {
    need(allowed.includes(args[i]) && !Object.hasOwn(result, args[i]) &&
      typeof args[i + 1] === 'string' && args[i + 1].length > 0,
      'WORKSPACE_ARGUMENT_INVALID_OR_REPEATED');
    result[args[i]] = args[i + 1];
  }
  return result;
}
function privateMode(info) { return (info.mode & 0o077) === 0; }
async function privateDirectory(path) {
  abs(path, 'WORKSPACE_PATH_NOT_ABSOLUTE');
  const info = await lstat(path);
  need(info.isDirectory() && !info.isSymbolicLink() && privateMode(info),
    'WORKSPACE_DIRECTORY_MUST_BE_PRIVATE');
  return info;
}
async function privateJson(path, max = 65536) {
  const file = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const info = await file.stat();
    need(info.isFile() && privateMode(info) && info.size <= max, 'WORKSPACE_FILE_NOT_PRIVATE');
    const raw = await file.readFile();
    need(raw.length <= max, 'WORKSPACE_FILE_TOO_LARGE');
    try { return JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(raw)); }
    catch { throw new InputError('WORKSPACE_JSON_INVALID'); }
  } finally { await file.close(); }
}
function keys(environment, { create = false } = {}) {
  const present = KEY_NAMES.filter(name => environment[name] !== undefined);
  need(present.length === 0 && create || present.length === KEY_NAMES.length,
    'WORKSPACE_OPERATOR_KEYS_INCOMPLETE');
  const result = {};
  for (const name of KEY_NAMES) {
    const value = present.length ? environment[name] : randomBytes(32).toString('base64');
    need(typeof value === 'string' && value.length <= 4096 &&
      /^[A-Za-z0-9+/]+={0,2}$/.test(value), 'WORKSPACE_OPERATOR_KEY_INVALID');
    const decoded = Buffer.from(value, 'base64');
    need(decoded.length >= 32 && decoded.toString('base64') === value,
      'WORKSPACE_OPERATOR_KEY_INVALID');
    result[name] = value;
  }
  return { values:result, source:present.length ? 'EXISTING_OPERATOR_ENVIRONMENT' : 'NEW_LOCAL_WORKSPACE' };
}

// This is the original Governor constructor, not a second ledger implementation.
const INITIALIZE_LEDGER = `import base64,json,os,sys
from pathlib import Path
if sys.version_info < (3,11): raise RuntimeError('PYTHON_311_REQUIRED')
sys.path.insert(0,sys.argv[1])
from governor import Governor
os.umask(0o077)
policy=json.loads(Path(sys.argv[2]).read_text())
keys=json.load(sys.stdin)
names=('SF36_CONSENT_KEY_B64','SF36_AUDIT_KEY_B64','SF36_OPERATOR_KEY_B64')
ledger=Governor(sys.argv[3],policy,*(base64.b64decode(keys[n],validate=True) for n in names))
try:
    count=ledger.db.execute('SELECT count(*) FROM reservations').fetchone()[0]
    if sys.argv[4] != 'resume' and count != 0: raise RuntimeError('NEW_LEDGER_NOT_EMPTY')
    ledger.db.execute('BEGIN')
    try: audit=ledger.audit()
    finally: ledger.db.execute('ROLLBACK')
    print(json.dumps({'schema':'stellar-forge.sf88.ledger-init.v1','reservations':count,'audit':audit,'journalMode':ledger.db.execute('PRAGMA journal_mode').fetchone()[0]}))
finally: ledger.close()
`;
async function initializeLedger(python, policy, ledger, keyValues, { resume = false } = {}) {
  return new Promise((accept, reject) => {
    const child = spawn(python, ['-I', '-B', '-c', INITIALIZE_LEDGER, governorPath, policy, ledger, resume ? 'resume' : 'create'], {
      shell:false, env:{LANG:'C.UTF-8', LC_ALL:'C.UTF-8'}, stdio:['pipe', 'pipe', 'ignore'],
    });
    let output = '', settled = false;
    const finish = (error, value) => {
      if (settled) return; settled = true; clearTimeout(timer);
      error ? reject(error) : accept(value);
    };
    const timer = setTimeout(() => {
      child.kill('SIGKILL'); finish(new InputError('WORKSPACE_LEDGER_INIT_TIMEOUT'));
    }, 15000);
    child.once('error', () => finish(new InputError('WORKSPACE_PYTHON_START_FAILED')));
    child.stdin.once('error', () => finish(new InputError('WORKSPACE_LEDGER_INIT_FAILED')));
    child.stdout.on('data', chunk => {
      output += chunk;
      if (output.length > 8192) {
        child.kill('SIGKILL'); finish(new InputError('WORKSPACE_LEDGER_INIT_FAILED'));
      }
    });
    child.once('close', code => {
      if (code !== 0) return finish(new InputError('WORKSPACE_LEDGER_INIT_FAILED'));
      try {
        const result = JSON.parse(output);
        need(result.schema === 'stellar-forge.sf88.ledger-init.v1' &&
          Number.isSafeInteger(result.reservations) && result.reservations >= 0 && (resume || result.reservations === 0) &&
          result.journalMode === 'wal' && result.audit?.outcome === 'JOURNAL_CONSISTENT', 'WORKSPACE_LEDGER_INIT_FAILED');
        finish(null, result);
      } catch { finish(new InputError('WORKSPACE_LEDGER_INIT_FAILED')); }
    });
    child.stdin.end(JSON.stringify(keyValues));
  });
}

/** Provision a NEW operator workspace from an existing offline-reviewed operation. */
export async function initializeWorkspace(args, { environment = process.env, resume = false } = {}) {
  need(process.platform !== 'win32', 'WORKSPACE_POSIX_OPERATOR_REQUIRED');
  const opt = options(args, ['--config', '--dir', '--actor', '--service', '--payer', '--python',
    '--secret-env', '--signer-provider', '--rpc', '--https-proxy', '--https-proxy-env',
    '--total-atomic', '--daily-atomic']);
  const inputPath = abs(opt['--config'], 'WORKSPACE_REVIEW_CONFIG_REQUIRED');
  const directory = resolve(abs(opt['--dir'], 'WORKSPACE_PATH_NOT_ABSOLUTE'));
  const source = await config(inputPath);
  need(['operator','signerModule','evidenceDir'].every(name => source[name] === undefined),
    'WORKSPACE_SOURCE_ALREADY_CONFIGURED');
  const op = operation(source.operation);
  const proxyUrl = opt['--https-proxy'], proxyEnv = opt['--https-proxy-env'];
  need(proxyUrl === undefined || proxyEnv === undefined, 'WORKSPACE_ONE_PROXY_SOURCE_REQUIRED');
  need(proxyUrl === undefined && proxyEnv === undefined || source.buyerTransport === undefined,
    'WORKSPACE_PROXY_CONFIG_AND_FLAG_CONFLICT');
  const transport = buyerTransport(proxyUrl === undefined && proxyEnv === undefined ? source : {
    ...source, buyerTransport:{mode:'explicit-connect', origin:new URL(op.url).origin,
      ...(proxyEnv === undefined ? {proxyUrl} : {proxyEnv})},
  });
  const ticket = await loadOperationTicket(op, {requireCurrent:true});
  need(Object.hasOwn(NETWORKS, op.expect.network), 'WORKSPACE_STELLAR_NETWORK_REQUIRED');
  need(/^C[A-Z2-7]{55}$/.test(op.expect.asset) && /^[GC][A-Z2-7]{55}$/.test(op.expect.payTo),
    'WORKSPACE_STELLAR_TERMS_INVALID');
  const payer = opt['--payer'];
  need(typeof payer === 'string' && /^G[A-Z2-7]{55}$/.test(payer), 'WORKSPACE_PAYER_REQUIRED');
  need(source.trustedPayer === undefined || source.trustedPayer === payer, 'WORKSPACE_PAYER_CONFLICT');
  const maximum = amount(op.expect.maxAtomic, 'WORKSPACE_SINGLE_AMOUNT_INVALID');
  const total = amount(opt['--total-atomic'] ?? maximum, 'WORKSPACE_TOTAL_AMOUNT_INVALID');
  const daily = amount(opt['--daily-atomic'] ?? total, 'WORKSPACE_DAILY_AMOUNT_INVALID');
  need(BigInt(total) >= BigInt(maximum) && BigInt(daily) >= BigInt(maximum) &&
    BigInt(daily) <= BigInt(total), 'WORKSPACE_BUDGET_LIMITS_INCONSISTENT');
  const signerProvider = opt['--signer-provider'];
  need(signerProvider === undefined || opt['--secret-env'] === undefined,
    'WORKSPACE_ONE_SIGNER_SOURCE_REQUIRED');
  const secretEnv = signerProvider === undefined ? opt['--secret-env'] ?? 'STELLAR_SECRET' : undefined;
  need(secretEnv === undefined || /^[A-Z][A-Z0-9_]{0,127}$/.test(secretEnv) && !KEY_NAMES.includes(secretEnv),
    'WORKSPACE_WALLET_ENV_NAME_INVALID');
  const owner = operator({python:opt['--python'], actor:opt['--actor'], service:opt['--service'],
    policy:join(directory, 'policy.json'), ledger:join(directory, 'reservations.sqlite')});
  need((await stat(owner.python)).isFile(), 'WORKSPACE_PYTHON_FILE_REQUIRED');
  await access(owner.python, constants.X_OK);
  // Resolve the parent once and refuse aliasing through a symlinked directory.
  need(await realpath(dirname(directory)) === dirname(directory), 'WORKSPACE_PARENT_PATH_AMBIGUOUS');
  const policy = {schema:'stellar-spend-governor/v1', assets:[{
    network:op.expect.network, asset:op.expect.asset,
    max_single:maximum, max_total:total, max_per_utc_day:daily,
    max_per_actor_utc_day:daily, max_per_service_utc_day:daily,
  }]};
  const cfg = {...source, operation:{...op,
    ...(ticket ? {ticketFile:join(directory, 'operation-ticket.json')} : {})}, operator:owner,
    ...(transport === null ? {} : {buyerTransport:transport}),
    signerModule:join(directory, 'signer.mjs'), evidenceDir:join(directory, 'evidence'),
    trustedPayer:payer};
  execution(cfg);
  const configuredBytes = Buffer.from(json(cfg));
  need(configuredBytes.length <= 65536, 'WORKSPACE_CONFIG_TOO_LARGE');
  const signerPins = {network:op.expect.network, asset:op.expect.asset, payTo:op.expect.payTo,
    maxAtomic:maximum, expectedPayer:payer, secretEnv, signerProvider, rpcUrl:opt['--rpc'],
    paymentFlow:op.expect.paymentFlow ?? 'authorization'};
  const {validateNativeSignerConfiguration, inspectSignerProvider} = await import('./native-signer.mjs');
  signerPins.rpcUrl = validateNativeSignerConfiguration(signerPins).rpcUrl;
  if (signerProvider !== undefined) await inspectSignerProvider(signerProvider);
  const factory = signerProvider === undefined ? 'createEnvironmentStellarSigner' : 'createProviderStellarSigner';
  const signerSource = `// Private operator adapter. No wallet key is stored in this file.\n` +
    `import {${factory}, validateNativeSignerInput} from ${JSON.stringify(signerUrl)};\n` +
    `const pins = Object.freeze(${JSON.stringify(signerPins)});\nlet adapter;\n` +
    `export async function sign(payload) {\n` +
    `  validateNativeSignerInput(payload, pins);\n` +
    `  adapter ??= ${factory}({...pins, environment:process.env});\n` +
    `  return (await adapter).sign(payload);\n}\n`;
  const body = await readRequestBody(op);
  const digest = value => createHash('sha256').update(value).digest('hex');
  const lease = await acquireInitialization(directory, { python: owner.python, resume }).catch(error => {
    if (error.code === 'EEXIST') throw new InputError('WORKSPACE_ALREADY_EXISTS');
    throw error;
  });
  try {
  const priorManifestBytes = await optionalInitializationBytes(join(directory, 'workspace.json'), 65536);
  const priorManifest = priorManifestBytes === null ? null : await privateJson(join(directory, 'workspace.json'));
  const checkpointBytes = await optionalInitializationBytes(join(directory, 'initializing.json'), 65536);
  const checkpoint = checkpointBytes === null ? null : await privateJson(join(directory, 'initializing.json'));
  const keyBytes = await optionalInitializationBytes(join(directory, 'operator-keys.json'), 16384);
  const ledgerInfo = await lstat(owner.ledger).catch(error => { if (error.code === 'ENOENT') return null; throw error; });
  if (ledgerInfo) need(ledgerInfo.isFile() && !ledgerInfo.isSymbolicLink() && privateMode(ledgerInfo), 'WORKSPACE_LEDGER_NOT_PRIVATE');
  need(!priorManifest || ledgerInfo, 'WORKSPACE_RESTORE_ORIGINAL_LEDGER');
  let keySet;
  if (keyBytes !== null) {
    const stored = await privateJson(join(directory, 'operator-keys.json'), 16384);
    need(stored.schema === SCHEMA && schemaObject(stored.keys) && Object.keys(stored.keys).length === KEY_NAMES.length,
      'WORKSPACE_KEY_FILE_INVALID');
    keySet = { values: keys(stored.keys).values,
      source: priorManifest?.operatorKeySource ?? checkpoint?.operatorKeySource ?? 'RETAINED_PRIVATE_WORKSPACE' };
    if (KEY_NAMES.some(name => environment[name] !== undefined)) {
      const supplied = keys(environment).values;
      need(KEY_NAMES.every(name => supplied[name] === keySet.values[name]), 'WORKSPACE_OPERATOR_KEYS_CHANGED');
    }
  } else {
    need(!ledgerInfo && !priorManifest, 'WORKSPACE_RESTORE_ORIGINAL_OPERATOR_KEYS');
    keySet = keys(environment, { create: true });
  }
  const manifest = {schema:SCHEMA, createdAt:priorManifest?.createdAt ?? checkpoint?.createdAt ?? new Date().toISOString(), directory,
    config:'operator.json', keys:'operator-keys.json', sourceCli:cliPath,
    sourceConfig:inputPath, signer:signerPins,
    ...(transport === null ? {} : {buyerTransport:transport}),
    operatorKeySource:keySet.source, walletKeyEnvironment:secretEnv, signerProvider,
    network:op.expect.network, payer};
    const initialization = { schema: 'stellar-forge.sf88.workspace-initialization.v1',
      createdAt: manifest.createdAt, directory, sourceConfig: inputPath,
      configSha256: digest(configuredBytes), policySha256: digest(json(policy)), signerSha256: digest(signerSource),
      bodySha256: body === undefined ? null : digest(body), bodyBytes: body?.length ?? 0,
      ticketSha256: ticket ? digest(ticket.sourceBytes) : null, operatorKeySource: keySet.source };
    const retainedFiles = [
      ['operator.json', configuredBytes], ['policy.json', json(policy)],
      ['operator-keys.json', json({schema:SCHEMA, keys:keySet.values})], ['signer.mjs', signerSource],
      ...(ticket ? [['operation-ticket.json', ticket.sourceBytes]] : []),
    ];
    if (resume) for (const [name, contents] of retainedFiles) {
      const present = await verifyInitializationFile(join(directory, name), contents);
      need(!ledgerInfo || present, 'WORKSPACE_RESTORE_ORIGINAL_INITIALIZATION_INPUTS');
    }
    if (!priorManifest) await retainInitializationRecord(join(directory, 'initializing.json'), initialization, { resume, ignore: ['createdAt'] });
    else if (checkpoint) await retainInitializationRecord(join(directory, 'initializing.json'), initialization, { resume: true, ignore: ['createdAt'] });
    await initializationDirectory(cfg.evidenceDir, { create: !ledgerInfo });
    for (const [name, contents] of retainedFiles)
      await retainInitializationFile(join(directory, name), contents, { resume });
    const ledger = await initializeLedger(owner.python, owner.policy, owner.ledger, keySet.values, { resume });
    // The manifest is written last; partial initialization is never executable.
    await retainInitializationRecord(join(directory, 'workspace.json'), manifest, { resume, ignore: ['createdAt'] });
    return {mode:priorManifest ? 'PRIVATE_OPERATOR_WORKSPACE_REOPENED' : lease.created ? 'PRIVATE_OPERATOR_WORKSPACE_CREATED' : 'PRIVATE_OPERATOR_WORKSPACE_RESUMED', directory,
      config:join(directory, 'operator.json'), network:manifest.network, payer,
      operatorKeySource:keySet.source, walletKeyEnvironment:secretEnv,
      operationTicket:operationTicketView(ticket),
      signerSource:signerProvider === undefined ? 'ENVIRONMENT' : 'TRUSTED_SEP43_PROVIDER',
      buyerTransport:transport, requestTimeoutMs:requestTimeoutMs(cfg), walletKeyStored:false, policy, ledger,
      commands:{review:[process.execPath, cliPath, '--review-workspace', '--dir', directory],
        execute:[process.execPath, cliPath, '--execute-workspace', '--dir', directory]}};
  } catch (error) {
    // Only remove the new directory this invocation owns, never an existing workspace.
    if (lease.created && !resume) {
      const current = await lstat(directory).catch(() => null);
      if (current?.dev === lease.identity.dev && current?.ino === lease.identity.ino)
        await rm(directory, {recursive:true, force:true}).catch(() => {});
    }
    throw error;
  } finally { await lease.close(); }
}

/** Review never opens the operator-key file or loads the signer/SDK. */
export async function openWorkspace(args, { execute = false, accounting = false,
  environment = process.env, storageDirectory } = {}) {
  need(typeof execute === 'boolean' && typeof accounting === 'boolean' && !(execute && accounting),
    'WORKSPACE_ONE_OPERATION_MODE_REQUIRED');
  need(process.platform !== 'win32', 'WORKSPACE_POSIX_OPERATOR_REQUIRED');
  const opt = options(args, ['--dir']);
  const directory = resolve(abs(opt['--dir'], 'WORKSPACE_PATH_NOT_ABSOLUTE'));
  // Recovery reviews an authenticated staged copy against its ORIGINAL paths.
  // It never relocates those identities or permits execution from staged bytes.
  need(storageDirectory===undefined||!execute,'WORKSPACE_STAGED_REVIEW_ONLY');
  const storage=storageDirectory===undefined?directory:
    resolve(abs(storageDirectory,'WORKSPACE_PATH_NOT_ABSOLUTE'));
  await privateDirectory(storage);
  const manifest = await privateJson(join(storage, 'workspace.json'));
  need(manifest.schema === SCHEMA && manifest.directory === directory &&
    manifest.config === 'operator.json' && manifest.keys === 'operator-keys.json',
    'WORKSPACE_MANIFEST_INVALID');
  const configPath = join(storage, manifest.config);
  await privateJson(configPath);
  const cfg = await config(configPath);
  const {op, owner, transport} = execution(cfg);
  need(Object.hasOwn(NETWORKS, op.expect.network) && op.expect.network === manifest.network &&
    cfg.trustedPayer === manifest.payer &&
    owner.policy === join(directory, 'policy.json') && owner.ledger === join(directory, 'reservations.sqlite') &&
    cfg.signerModule === join(directory, 'signer.mjs') && cfg.evidenceDir === join(directory, 'evidence'),
    'WORKSPACE_CONFIG_BINDING_CHANGED');
  need(JSON.stringify(transport) === JSON.stringify(buyerTransport({
    operation:cfg.operation, buyerTransport:manifest.buyerTransport,
  })), 'WORKSPACE_TRANSPORT_BINDING_CHANGED');
  need(schemaObject(manifest.signer) && manifest.signer.network === op.expect.network &&
    manifest.signer.asset === op.expect.asset && manifest.signer.payTo === op.expect.payTo &&
    manifest.signer.expectedPayer === cfg.trustedPayer &&
    (manifest.signer.paymentFlow ?? 'authorization') === (op.expect.paymentFlow ?? 'authorization') &&
    BigInt(amount(op.expect.maxAtomic, 'WORKSPACE_SINGLE_AMOUNT_INVALID')) <=
      BigInt(amount(manifest.signer.maxAtomic, 'WORKSPACE_SIGNER_CAP_INVALID')),
    'WORKSPACE_SIGNER_BINDING_CHANGED');
  await privateDirectory(join(storage,'evidence'));
  let operatorEnvironment;
  if (execute || accounting) {
    // Surface missing local setup before an inbox attempt or SF36 reservation.
    // Accounting reopens the original journal keys without requiring a wallet,
    // importing its provider or constructing a signer after the purchase.
    if (execute) {
      if (transport !== null) resolveBuyerProxy(transport, environment);
      const {checkNativeSignerPrerequisites} = await import('./native-signer.mjs');
      await checkNativeSignerPrerequisites({...manifest.signer, environment});
    }
    const stored = await privateJson(join(storage, manifest.keys), 16384);
    need(stored.schema === SCHEMA && schemaObject(stored.keys) &&
      Object.keys(stored.keys).length === KEY_NAMES.length, 'WORKSPACE_KEY_FILE_INVALID');
    // The three journal keys come from the original private workspace. Only
    // execution receives SF81's validated, ephemeral host approval transport;
    // it is never read from the manifest or written into operator-keys.json.
    operatorEnvironment = {...keys(stored.keys).values,
      ...(execute ? operatorApprovalEnvironment(environment) : {})};
  }
  return {config:cfg, configPath, manifest, operatorEnvironment};
}

/** Review the original workspace plus package/source availability, without custody. */
export async function diagnoseWorkspace(args, {environment = process.env} = {}) {
  const workspace = await openWorkspace(args);
  const {manifest} = workspace;
  const {inspectNativeSignerRuntime, inspectSignerProvider, validateNativeSignerConfiguration} =
    await import('./native-signer.mjs');
  const checks = [];
  let sdk = null;
  const code = error => /^[A-Z0-9_]{1,120}$/.test(error?.code ?? '')
    ? error.code : 'WORKSPACE_RUNTIME_UNAVAILABLE';
  const pins = validateNativeSignerConfiguration(manifest.signer);
  const transport = buyerTransport(workspace.config);
  const browserSelected = environment.SF81_APPROVAL_SOCKET !== undefined ||
    environment.SF81_APPROVAL_TOKEN !== undefined;
  const approvalCheck = browserSelected ? 'operator-browser' : 'operator-terminal';
  try {
    await checkOperatorChannel(workspace.config.operation.intentId, {environment});
    checks.push({check:approvalCheck, status:'AVAILABLE'});
  } catch (error) {
    checks.push({check:approvalCheck, status:'UNAVAILABLE', code:code(error)});
  }
  if (transport !== null) {
    try {
      resolveBuyerProxy(transport, environment);
      checks.push({check:'merchant-proxy', status:'VALIDATED',
        ...(transport.proxyEnv === undefined ? {} : {name:transport.proxyEnv})});
    } catch (error) {
      checks.push({check:'merchant-proxy', status:'UNAVAILABLE', code:code(error),
        ...(transport.proxyEnv === undefined ? {} : {name:transport.proxyEnv})});
    }
  }
  try {
    sdk = await inspectNativeSignerRuntime(pins.network);
    checks.push({check:'official-sdk', status:'AVAILABLE'});
  } catch (error) { checks.push({check:'official-sdk', status:'UNAVAILABLE', code:code(error)}); }
  const provider = manifest.signer.signerProvider;
  if (provider !== undefined) {
    try {
      await inspectSignerProvider(provider);
      checks.push({check:'signer-provider', status:'PRESENT_NOT_IMPORTED', filename:basename(provider)});
    } catch (error) {
      checks.push({check:'signer-provider', status:'UNAVAILABLE', code:code(error)});
    }
  } else {
    const name = manifest.signer.secretEnv ?? 'STELLAR_SECRET';
    checks.push({check:'key-environment', name,
      status:Object.hasOwn(environment, name) ? 'PRESENT_NOT_LOADED' : 'MISSING'});
  }
  const ready = checks.every(check => !['UNAVAILABLE','MISSING'].includes(check.status));
  return {mode:'OPERATOR_WORKSPACE_DIAGNOSTICS', status:ready ? 'READY_TO_EXECUTE' : 'SETUP_REQUIRED',
    directory:manifest.directory, network:pins.network, payer:pins.expectedPayer,
    signerSource:provider === undefined ? 'ENVIRONMENT' : 'TRUSTED_SEP43_PROVIDER',
    rpcOrigin:new URL(pins.rpcUrl).origin, buyerTransport:buyerTransport(workspace.config),
    requestTimeoutMs:requestTimeoutMs(workspace.config), sdk, checks,
    next:ready ? 'Review the operation, then use --execute-workspace for original operator approval.' :
      'Resolve the listed runtime requirements and diagnose this same workspace again.'};
}

// MIT. Live request admission for actual SF30/SF61 imported seller offers.
// Reuses the exact original SF25 Draft 2020-12 validator; never touches payment.
import { validateBazaarExtension } from '../../../stellar-forge/payment-auto-catalog/schema-validation.mjs';
import { supportsSellerMethod } from '../sf30-seller-sdk/http-methods.mjs';
import { decodeQueryParameters, validateQuerySerialization } from '../sf30-seller-sdk/query-parameters.mjs';

const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const own = (value, key) => Object.hasOwn(value, key);
const rejected = (code = 'LIVE_REQUEST_SCHEMA_REJECTED', issues = []) => ({
  status: 422,
  body: { error: code, ...(issues.length ? { issues: issues.slice(0, 5) } : {}) },
});


/** Construct one trusted admission callback per ORIGINAL imported offer.
 *
 * At runtime the SF30 resource router has already selected method/path and
 * decoded pathParams. It invokes this callback only in NATIVE_X402 mode before
 * processHTTPRequest, never during challenge-only metadata display.
 */
export function createLiveRequestAdmission(offer) {
  const extension = offer?.extensions?.bazaar;
  const verification = validateBazaarExtension(extension);
  if (!verification.ok) throw new TypeError('Original imported Bazaar schema is invalid: ' + verification.reason);
  const reference = extension.info?.input;
  const schemaInput = extension.schema?.properties?.input;
  if (!object(reference) || reference.type !== 'http' ||
      !supportsSellerMethod(reference.method) ||
      !object(schemaInput) || !object(schemaInput.properties)) {
    throw new TypeError('A supported SF30 HTTP Bazaar offer is required');
  }
  const properties = schemaInput.properties;
  const querySchema = properties.queryParams;
  const querySerialization = structuredClone(extension.querySerialization);
  validateQuerySerialization(querySchema, querySerialization);
  const pathSchema = properties.pathParams;
  const bodySchema = properties.body;
  // A genuine imported schema, not an advertiser-supplied "required" guess.
  const method = reference.method;
  const originalInfo = structuredClone(extension.info);
  const originalSchema = structuredClone(extension.schema);

  return function admitLiveRequest(context) {
    if (!object(context) || context.method !== method || context.signal?.aborted) {
      return rejected('LIVE_REQUEST_METHOD_REJECTED');
    }
    let query;
    try { query = decodeQueryParameters(context.query ?? {}, querySchema, querySerialization); }
    catch { return rejected('LIVE_QUERY_PARAMETERS_REJECTED'); }
    const input = structuredClone(originalInfo.input);
    // Strip the seller's examples; they MUST NOT satisfy actual request fields.
    delete input.queryParams;
    delete input.pathParams;
    delete input.body;
    if (querySchema) input.queryParams = query;
    if (pathSchema) {
      if (!object(context.pathParams)) return rejected('LIVE_PATH_PARAMETERS_REJECTED');
      input.pathParams = { ...context.pathParams };
    } else if (context.pathParams && Object.keys(context.pathParams).length) {
      return rejected('LIVE_PATH_PARAMETERS_REJECTED');
    }
    if (bodySchema) {
      const absent=context.bodyPresent===false||context.bodyPresent===undefined&&context.body===undefined;
      if (!absent || schemaInput.required?.includes('body')) input.body = context.body === undefined ? null : context.body;
    } else if (context.body !== undefined && context.body !== null) {
      return rejected('LIVE_BODY_NOT_DECLARED');
    }
    const check = validateBazaarExtension({
      info: { ...originalInfo, input },
      schema: originalSchema,
    });
    if (!check.ok) {
      // Exact original schema failures, but never echo input values or payload.
      const issues = (check.errors ?? []).filter(x => typeof x === 'string')
        .map(x => x.slice(0, 160));
      return rejected('LIVE_REQUEST_SCHEMA_REJECTED', issues);
    }
    return true;
  };
}

/** Convenience adapter for the exact operator-created seller-service config.
 * Export the returned function under a route's existing admit binding name.
 */
export function admissionForServiceRoute(config, id) {
  if (config?.schema !== 'stellar-forge.seller-service.v1' || !Array.isArray(config.routes)) {
    throw new TypeError('Original SF30 seller-service config required');
  }
  const routes = config.routes.filter(route => route?.id === id);
  if (routes.length !== 1 || !object(routes[0].offer)) {
    throw new TypeError('Expected exactly one original imported offer with route id ' + id);
  }
  return createLiveRequestAdmission(routes[0].offer);
}

// MIT. Read-only SF30 runtime evidence packaging; does not call paid routes or a wallet.
import { request } from 'node:http';
import { createHash } from 'node:crypto';
import { supportsSellerMethod } from '../sf30-seller-sdk/http-methods.mjs';
import { deliveryPrometheus, summarizeOutbox } from '../sf30-seller-sdk/operations/delivery-view.mjs';
import { mkdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const MAX_BYTES = 2_000_000;
const MAX_ROUTES = 103;
// Read the maintained collector's actual names; do not duplicate its counters.
const DELIVERY_GAUGES = new Set(deliveryPrometheus(summarizeOutbox([])).split('\n')
  .filter(line => line && !line.startsWith('#')).map(line => line.split(' ')[0]));
function originalMetric(line) {
  if (!line || line.startsWith('#')) return true;
  if (/^sf30_http_(requests_total|active_requests|responses_total|aborted_total|request_duration_seconds_(bucket|sum|count))\{[^\r\n]*\} (\d+|\d+\.\d+|\d+e[+-]?\d+)$/i.test(line)) return true;
  const match = /^([a-z0-9_]+) (\d+)$/.exec(line);
  return Boolean(match && DELIVERY_GAUGES.has(match[1]) && Number.isSafeInteger(Number(match[2])));
}
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
const own = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const object = o => o !== null && typeof o === 'object' && !Array.isArray(o);
const iso = value => typeof value === 'string' && !Number.isNaN(Date.parse(value)) && new Date(value).toISOString() === value;
const positive = n => Number.isSafeInteger(n) && n >= 0;
const invalid = reason => { throw new Error('SF93_SOURCE_INVALID: ' + reason); };
const text = value => String(value).replaceAll('|', '\\|').replace(/[\r\n\t]/g, ' ').replace(/[<>]/g, '');
const tableCell = value => text(value ?? 'n/a');

export function loopbackOrigin(input, field) {
  let url;
  try { url = new URL(input); } catch { throw new TypeError(`${field} must be an explicit loopback HTTP origin`); }
  if (url.protocol !== 'http:' || url.hostname !== '127.0.0.1' || !url.port ||
      !/^\d+$/.test(url.port) || Number(url.port) < 1 || Number(url.port) > 65535 ||
      url.username || url.password || url.pathname !== '/' || url.search || url.hash ||
      input !== url.origin) {
    throw new TypeError(`${field} must be http://127.0.0.1:PORT with no path, query, credentials or fragment`);
  }
  return url.origin;
}

export async function readLocal(origin, path, contentType, {signal} = {}) {
  const address = new URL(path, origin);
  const bytes = await new Promise((done, fail) => {
    const req = request(address, { method: 'GET', agent: false, signal, timeout: 5000,
      headers: { accept: contentType, 'accept-encoding': 'identity' } }, res => {
      if (res.statusCode !== 200 || !String(res.headers['content-type'] ?? '').startsWith(contentType)) {
        req.destroy(); fail(new Error(`SF93_ENDPOINT: ${path} returned HTTP ${res.statusCode} or unexpected type`)); return;
      }
      const chunks = []; let total = 0;
      res.on('data', b => {
        total += b.length;
        if (total > MAX_BYTES) { req.destroy(new Error(`SF93_SIZE: ${path} exceeds ${MAX_BYTES} bytes`)); return; }
        chunks.push(b);
      });
      res.once('end', () => done(Buffer.concat(chunks)));
      res.once('error', fail);
      res.once('aborted', () => fail(new Error(`SF93_ENDPOINT: ${path} aborted`)));
    });
    const deadline = setTimeout(() => req.destroy(new Error(`SF93_TIMEOUT: ${path}`)), 5000);
    req.once('close', () => clearTimeout(deadline));
    req.once('timeout', () => req.destroy(new Error(`SF93_TIMEOUT: ${path}`)));
    req.once('error', fail);
    req.end();
  });
  return { bytes, sha256: sha256(bytes), at: new Date().toISOString() };
}

function parseJson(receipt, name) {
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(receipt.bytes)); }
  catch { invalid(`${name} is not valid UTF-8 JSON`); }
}

function stats(row, id = 'stats') {
  if (!object(row) || !['started','completed','responses','inFlight','success','challenge',
      'clientError','serverError','other','disconnected'].every(k => positive(row[k]))) invalid(`${id} counters`);
  if (row.completed > row.started || row.inFlight !== row.started - row.completed ||
      row.responses + row.disconnected !== row.completed ||
      row.success + row.challenge + row.clientError + row.serverError + row.other !== row.responses) {
    invalid(`${id} counter conservation`);
  }
  if (!object(row.statuses) || Object.entries(row.statuses).some(([k,v]) => !/^[1-5]\d\d$/.test(k) || !positive(v)) ||
      Object.values(row.statuses).reduce((a,b) => a+b,0) !== row.responses) invalid(`${id} status totals`);
  for (const [k,v] of Object.entries(row.statuses)) {
    if (k === '402' && v > row.challenge) invalid(`${id} 402 challenge mismatch`);
  }
  const result = {};
  for (const key of ['id','method','path','started','completed','responses','inFlight','success',
    'challenge','clientError','serverError','other','disconnected','durationMeanMs','durationMaxMs',
    'latencyP95UpperBoundMs','httpSuccessPercent']) if (own(row,key)) result[key]=row[key];
  result.statuses = Object.fromEntries(Object.entries(row.statuses));
  return result;
}

export function compileBundle({ sellerHealth, sellerOffers, opsSnapshot, metrics, receipts, generatedAt }) {
  if (!object(sellerHealth) || sellerHealth.schema !== 'stellar-forge.seller-service.v1' ||
      !['CHALLENGE_ONLY','NATIVE_X402'].includes(sellerHealth.mode) ||
      !Array.isArray(sellerHealth.routes) || sellerHealth.routes.length < 1 || sellerHealth.routes.length > 64) {
    invalid('original seller health');
  }
  if (!Array.isArray(sellerOffers) || sellerOffers.length !== sellerHealth.routes.length) invalid('seller offer count mismatch');
  if (!object(opsSnapshot) || opsSnapshot.schema !== 'stellar-forge.seller-traffic.v1' ||
      !/^[0-9a-f-]{36}$/i.test(opsSnapshot.sessionId ?? '') || !iso(opsSnapshot.startedAt) ||
      !iso(opsSnapshot.capturedAt) || opsSnapshot.mode !== sellerHealth.mode ||
      !Array.isArray(opsSnapshot.routes) || opsSnapshot.routes.length !== sellerHealth.routes.length + 3 ||
      opsSnapshot.routes.length > MAX_ROUTES || !Array.isArray(opsSnapshot.recent) ||
      !Array.isArray(opsSnapshot.minutes) || opsSnapshot.minutes.length !== 60 ||
      !positive(opsSnapshot.recentLimit) || opsSnapshot.recent.length > opsSnapshot.recentLimit ||
      opsSnapshot.recentLimit > 2000 || !positive(opsSnapshot.observerErrors) ||
      !positive(opsSnapshot.ignoredMetadata) || typeof opsSnapshot.attached !== 'boolean') {
    invalid('original traffic snapshot schema');
  }
  if (typeof metrics !== 'string' || metrics.length > MAX_BYTES ||
      !metrics.includes('# TYPE sf30_http_requests_total counter') ||
      metrics.split('\n').some(line => !originalMetric(line))) {
    invalid('original metrics format');
  }
  const keyOf = row => `${row.id}\u0000${row.method}`;
  const routes = opsSnapshot.routes.map(r => stats(r, `route ${r.id}`));
  const live = routes.filter(r => !r.id.startsWith('@'));
  const special = routes.filter(r => r.id.startsWith('@')).map(r => r.id).sort();
  if (JSON.stringify(special) !== JSON.stringify(['@invalid','@method','@unmatched'])) invalid('original traffic special buckets');
  const healthKeys = new Set();
  for (const h of sellerHealth.routes) {
    if (!object(h) || !/^[A-Za-z0-9_-]{1,80}$/.test(h.id) || !supportsSellerMethod(h.method) ||
        healthKeys.has(keyOf(h))) invalid('health route declaration');
    healthKeys.add(keyOf(h));
  }
  if (live.length !== healthKeys.size || live.some(r => !healthKeys.has(keyOf(r))) ||
      new Set(live.map(keyOf)).size !== live.length) invalid('health/traffic route mismatch');
  const totals = stats(opsSnapshot.totals,'totals');
  for (const field of ['started','completed','responses','inFlight','success','challenge','clientError',
      'serverError','other','disconnected']) {
    if (routes.reduce((sum,r) => sum + r[field],0) !== totals[field]) invalid(`aggregate mismatch: ${field}`);
  }
  const recent = opsSnapshot.recent.map(r => {
    if (!object(r) || !positive(r.requestId) || !iso(r.at) ||
        !routes.some(row => row.id === r.routeId) ||
        !['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS','CONNECT','TRACE','OTHER'].includes(r.method) ||
        !['success','challenge','clientError','serverError','other','disconnected'].includes(r.outcome) ||
        !(r.status === null || Number.isInteger(r.status) && r.status >= 100 && r.status <= 599) ||
        !Number.isFinite(r.durationMs) || r.durationMs < 0) invalid('bounded recent outcome');
    return {requestId:r.requestId,at:r.at,routeId:r.routeId,method:r.method,outcome:r.outcome,
      status:r.status,durationMs:r.durationMs};
  });
  const minutes = opsSnapshot.minutes.map(m => {
    // Minute buckets have starts and finishes on their respective event clocks.
    // A completion in this minute may belong to a request started in an earlier minute.
    if (!object(m) || !iso(m.minute) || !['started','completed','responses','success',
        'challenge','serverError','disconnected'].every(k => positive(m[k])) ||
        m.responses + m.disconnected !== m.completed) invalid('minute counters');
    return {minute:m.minute,started:m.started,completed:m.completed,responses:m.responses,
      success:m.success,challenge:m.challenge,serverError:m.serverError,disconnected:m.disconnected};
  });
  const alerts = [];
  if (!opsSnapshot.attached) alerts.push('Traffic observer detached: later requests are not included.');
  if (opsSnapshot.observerErrors) alerts.push(`Observer reported ${opsSnapshot.observerErrors} internal errors: counts can be incomplete.`);
  if (totals.serverError) alerts.push(`${totals.serverError} finished HTTP 5xx response(s): review original application and upstream errors.`);
  if (totals.disconnected) alerts.push(`${totals.disconnected} disconnected request(s): investigate timeout/abandonment.`);
  if (routes.some(r => r.id === '@invalid' && r.started)) alerts.push('Invalid request targets reached the listener.');
  if (!totals.started) alerts.push('No observed resource requests in this session: no buyer adoption conclusion.');
  if (totals.challenge) alerts.push(`${totals.challenge} payment challenges are normal unpaid 402 flows, not merchant transactions.`);
  if (!alerts.length) alerts.push('No HTTP error signals in the captured window. Payment and merchant acceptance remain separate.');
  const report = {
    schema:'stellar-forge.seller-support.v1', generatedAt, seller: {mode:sellerHealth.mode,
      advertisedRoutes:sellerHealth.routes.map(h=>({id:h.id,method:h.method, admission:Boolean(h.admission)})),
      offerCount:sellerOffers.length},
    observation:{sessionId:opsSnapshot.sessionId,startedAt:opsSnapshot.startedAt,capturedAt:opsSnapshot.capturedAt,
      attached:opsSnapshot.attached,observerErrors:opsSnapshot.observerErrors,ignoredMetadata:opsSnapshot.ignoredMetadata,
      recentLimit:opsSnapshot.recentLimit,totals,routes,recent,minutes},
    alerts, coverage:{sellerInfo:'original SF30 seller local metadata',
      traffic:'original SF30 in-memory observer since attachment',
      metrics:'original SF30 operations Prometheus collector, fetched separately',
      payment:'NOT VERIFIED: HTTP status is not an on-chain settlement or revenue receipt',
      merchant:'NOT VERIFIED: no signed contract or customer acceptance inferred',
      samples:'sequential endpoint reads, not an atomic multi-endpoint snapshot'},
    sourceDigests:Object.fromEntries(Object.entries(receipts).map(([path,r])=>[path,{sha256:r.sha256,bytes:r.bytes.length,readAt:r.at}]))
  };
  const top = [...live].sort((a,b) => b.serverError-a.serverError || b.disconnected-a.disconnected || b.started-a.started);
  const rows = top.map(r=>`| ${tableCell(r.id)} | ${tableCell(r.method)} | ${r.started} | ${r.statuses['402']??0} | ${r.serverError} | ${r.disconnected} | ${tableCell(r.latencyP95UpperBoundMs)} |`).join('\n');
  const brief = `# SF30 seller · private operator support handoff\n\nGenerated: ${generatedAt}  \nObserver session: \`${opsSnapshot.sessionId}\`  \nObserved since: ${opsSnapshot.startedAt}  \nSnapshot at: ${opsSnapshot.capturedAt}  \nSeller mode: **${sellerHealth.mode}**  \nAdvertised routes: **${sellerHealth.routes.length}**\n\n## Runtime outcomes\n\nRequests **${totals.started}**, completed **${totals.completed}**, still in flight **${totals.inFlight}**, 2xx **${totals.success}**, payment challenges **${totals.challenge}**, HTTP 5xx **${totals.serverError}**, disconnected **${totals.disconnected}**. A request is an HTTP attempt, not a buyer, on-chain payment, fulfilled order or dollar of revenue.\n\n| Merchant route | Method | Attempts | 402 | 5xx | Disconnects | p95 bin upper bound, ms |\n|---|---|---:|---:|---:|---:|---:|\n${rows || '| None | | | | | | |'}\n\n## Operational review\n\n${alerts.map(a=>'- '+a).join('\n')}\n\n## Custody and next handoff\n\n- The original seller health, full offers and operational snapshot were read from the operator’s own loopback listeners. **Full offer terms are not copied into this handoff**; hashes and advertised route identifiers are retained.\n- Use \`bundle.json\` for machine-readable source-bound counts, \`metrics.prom\` for the original Prometheus exposition, and \`manifest.json\` for per-file/source SHA-256.\n- Route IDs and templates are the ORIGINAL configured merchant labels. The bundle contains no request URLs, customer query values, bodies, headers, IPs, wallet keys or full offers. Treat traffic and route names as private merchant operational information.\n- The traffic snapshot and metrics are sequential reads, not an atomic view. Metrics counters may change after the JSON capture. A server-side 2xx finish does not establish client receipt or on-chain payment. Consult the actual native payment and independent ledger/receipt tools to make payment claims.\n- Share with the existing SF49 merchant owner only after reviewing the private operational content; never post real merchant logs, offers or commercial terms to a public repo or issue.\n`;
  return { report, brief };
}

export async function readSupportBundle({seller,ops,signal}) {
  const sellerOrigin = loopbackOrigin(seller,'--seller');
  const opsOrigin = loopbackOrigin(ops,'--ops');
  const receipts = {};
  // Merchant metadata and operator evidence are fetched read-only; NO paid route or checkout request.
  for (const [name,origin,path,type] of [
    ['sellerHealth',sellerOrigin,'/_seller/health','application/json'],
    ['sellerOffers',sellerOrigin,'/_seller/offers','application/json'],
    ['opsSnapshot',opsOrigin,'/api/snapshot','application/json'],
    ['metrics',opsOrigin,'/metrics','text/plain']]) {
    receipts[name] = await readLocal(origin,path,type,{signal});
  }
  const generatedAt = new Date().toISOString();
  const {report,brief} = compileBundle({
    sellerHealth:parseJson(receipts.sellerHealth,'health'),
    sellerOffers:parseJson(receipts.sellerOffers,'offers'),
    opsSnapshot:parseJson(receipts.opsSnapshot,'ops snapshot'),
    metrics:new TextDecoder('utf-8',{fatal:true}).decode(receipts.metrics.bytes),
    receipts,generatedAt
  });
  const files = {
    'bundle.json':Buffer.from(JSON.stringify(report,null,2)+'\n'),
    'operator-brief.md':Buffer.from(brief),
    'metrics.prom':receipts.metrics.bytes
  };
  const entries = Object.fromEntries(Object.entries(files).map(([name,bytes])=>[name,{sha256:sha256(bytes),bytes:bytes.length}]));
  files['manifest.json'] = Buffer.from(JSON.stringify({schema:'stellar-forge.seller-support-manifest.v1',
    sessionId:report.observation.sessionId,generatedAt,files:entries,sourceDigests:report.sourceDigests},null,2)+'\n');
  for (const [name,bytes] of Object.entries(files))
    if (bytes.length > MAX_BYTES) throw new Error(`SF93_SIZE: ${name} exceeds ${MAX_BYTES} bytes`);
  return {report,brief,files};
}

export async function captureBundle({seller,ops,out,signal}) {
  const folder = resolve(out ?? '');
  if (!out || folder === '/' || folder === process.cwd()) throw new TypeError('--out must be a new private directory');
  const {report,files} = await readSupportBundle({seller,ops,signal});
  await mkdir(folder,{mode:0o700}); // Create-only. A prior directory is never overwritten.
  for (const [name,bytes] of Object.entries(files)) await writeFile(resolve(folder,name),bytes,{flag:'wx',mode:0o600});
  return {out:folder,sessionId:report.observation.sessionId,files:Object.keys(files),alerts:report.alerts,
    sourceDigests:report.sourceDigests};
}

export function parseArgs(args) {
  if (args.length === 1 && args[0] === '--help') return null;
  const options = {};
  for (let i=0;i<args.length;i+=2) {
    const key = args[i];
    if (!['--seller','--ops','--out'].includes(key) || !args[i+1] || own(options,key) || args[i+1].startsWith('--'))
      throw new TypeError('Usage: node bundle.mjs --seller http://127.0.0.1:8423 --ops http://127.0.0.1:8424 --out /private/NEW_DIR');
    options[key]=args[i+1];
  }
  if (Object.keys(options).length!==3) throw new TypeError('Required: --seller --ops --out');
  return {seller:options['--seller'],ops:options['--ops'],out:options['--out']};
