      // its session or retained cleanup, then closes the exact resulting owner.
      await startup;
      for (const name of ['operations-startup', 'operations', 'seller-startup', 'seller']) {
        const owner = owners.get(name);
        if (!owner) continue;
        await owner.close();
        owners.delete(name);
